export interface Product {
  id: string;
  fornecedor: string;
  codigo: string;
  situacao: string;
  comprador: string;
  produto: string;
  sabor: string;
  embalagem: string;
  estoqueMarsil: number;
  estoqueBoraceia: number;
}

export type RequestType = 'Teste' | 'Venda Garantida';

export interface StockRequest {
  id: string;
  productId: string;
  productName: string;
  productCode: string;
  quantidade: number;
  tipo: RequestType;
  solicitante: string;
  dataSolicitacao: string; // ISO format
  status: 'Pendente' | 'Aprovado' | 'Recusado';
}

export interface UpdateLog {
  id: string;
  timestamp: string;
  fileName: string;
  recordCount: number;
  status: 'success' | 'error';
  errorMessage?: string;
}

export interface AppState {
  products: Product[];
  requests: StockRequest[];
  updateHistory: UpdateLog[];
}

import React, { useState, useEffect } from 'react';
import { UserPortal } from './components/UserPortal';
import { AdminPortal } from './components/AdminPortal';
import { AppState, Product, StockRequest, UpdateLog } from './types';
import { LayoutDashboard, Users, ShieldCheck, Github } from 'lucide-react';

const STORAGE_KEY = 'marsil_boraceia_db_v1';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'user' | 'admin'>('user');
  const [appState, setAppState] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      return {
        products: parsed.products || [],
        requests: parsed.requests || [],
        updateHistory: parsed.updateHistory || []
      };
    }
    return { products: [], requests: [], updateHistory: [] };
  });

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(appState));
  }, [appState]);

  const handleUploadData = (newProducts: Product[]) => {
    setAppState(prev => ({ ...prev, products: newProducts }));
  };

  const handleRegisterUpdate = (log: UpdateLog) => {
    setAppState(prev => ({
      ...prev,
      updateHistory: [log, ...prev.updateHistory]
    }));
  };

  const handleSubmitRequest = (req: Omit<StockRequest, 'id' | 'dataSolicitacao' | 'status'>) => {
    const newRequest: StockRequest = {
      ...req,
      id: `req-${Date.now()}`,
      dataSolicitacao: new Date().toISOString(),
      status: 'Pendente'
    };
    setAppState(prev => ({
      ...prev,
      requests: [newRequest, ...prev.requests]
    }));
  };

  const handleUpdateRequestStatus = (requestId: string, status: StockRequest['status']) => {
    setAppState(prev => ({
      ...prev,
      requests: prev.requests.map(r => r.id === requestId ? { ...r, status } : r)
    }));
  };

  const handleClearRequests = () => {
    if (window.confirm('Deseja realmente apagar todo o histórico de solicitações?')) {
      setAppState(prev => ({ ...prev, requests: [] }));
    }
  };

  return (
    <div className="min-h-screen flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <div className="bg-blue-600 p-2 rounded-lg">
                <LayoutDashboard className="w-6 h-6 text-white" />
              </div>
              <div>
                <h1 className="text-xl font-bold bg-gradient-to-r from-blue-700 to-blue-500 bg-clip-text text-transparent">
                  Marsil & Boracéia
                </h1>
                <p className="text-[10px] text-gray-400 font-bold tracking-widest uppercase">
                  Gestão de Estoque
                </p>
              </div>
            </div>

            <nav className="flex space-x-1 bg-gray-100 p-1 rounded-xl">
              <button
                onClick={() => setActiveTab('user')}
                className={`flex items-center gap-2 px-4 py-2 text-sm font-semibold rounded-lg transition-all ${
                  activeTab === 'user' 
                    ? 'bg-white text-blue-600 shadow-sm' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                <Users className="w-4 h-4" />
                Vendedor
              </button>
              <button
                onClick={() => setActiveTab('admin')}
                className={`flex items-center gap-2 px-4 py-2 text-sm font-semibold rounded-lg transition-all ${
                  activeTab === 'admin' 
                    ? 'bg-white text-blue-600 shadow-sm' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                <ShieldCheck className="w-4 h-4" />
                Admin
              </button>
            </nav>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-grow p-4 sm:p-6 lg:p-8 bg-gray-50">
        {activeTab === 'user' ? (
          <UserPortal 
            products={appState.products} 
            requests={appState.requests}
            onSubmitRequest={handleSubmitRequest}
          />
        ) : (
          <AdminPortal 
            appState={appState}
            onUploadData={handleUploadData}
            onRegisterUpdate={handleRegisterUpdate}
            onUpdateRequestStatus={handleUpdateRequestStatus}
            onClearRequests={handleClearRequests}
          />
        )}
      </main>

      {/* Footer */}
      <footer className="bg-white border-t border-gray-100 py-6">
        <div className="max-w-7xl mx-auto px-4 flex flex-col md:flex-row justify-between items-center gap-4 text-gray-400 text-sm">
          <p>© 2024 Marsil Logística. Todos os direitos reservados.</p>
          <div className="flex items-center gap-4">
            <span className="flex items-center gap-1">
              <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
              Sistema Operacional
            </span>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Upload, ListChecks, Database, FileText, CheckCircle, XCircle, Trash2, Users, History, CheckCircle2, AlertCircle } from 'lucide-react';
import { Product, StockRequest, AppState, UpdateLog } from '../types';
import { StatsCard } from './StatsCard';

interface AdminPortalProps {
  appState: AppState;
  onUploadData: (newProducts: Product[]) => void;
  onRegisterUpdate: (log: UpdateLog) => void;
  onUpdateRequestStatus: (requestId: string, status: StockRequest['status']) => void;
  onClearRequests: () => void;
}

export const AdminPortal: React.FC<AdminPortalProps> = ({ 
  appState, 
  onUploadData, 
  onRegisterUpdate,
  onUpdateRequestStatus,
  onClearRequests
}) => {
  const [dragActive, setDragActive] = useState(false);
  const [uploadStatus, setUploadStatus] = useState<string | null>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement> | React.DragEvent) => {
    let file: File | null = null;
    if ('files' in e.target && e.target.files) {
      file = e.target.files[0];
    } else if ('dataTransfer' in e && e.dataTransfer.files) {
      file = e.dataTransfer.files[0];
    }

    if (!file) return;

    setUploadStatus('Lendo arquivo...');
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        // Mock parsing for CSV format as per the image
        // Headers: FORNECEDOR, NOVO CODIGO, CODIGO, SITUACAO, COMPRADOR, PRODUTO, SABOR, EMBALAGEM, ESTOQUE_MARSIL, ESTOQUE_BORACEIA
        const rows = text.split('\n').filter(r => r.trim() !== '');
        const dataRows = rows.slice(1); // Remove header

        const parsedProducts: Product[] = dataRows.map((row, index) => {
          const cols = row.split(/,|;/); // Basic split
          return {
            id: `p-${index}`,
            fornecedor: cols[0]?.trim() || 'N/A',
            codigo: cols[2]?.trim() || '0',
            situacao: cols[3]?.trim() || '',
            comprador: cols[4]?.trim() || '',
            produto: cols[5]?.trim() || '',
            sabor: cols[6]?.trim() || '',
            embalagem: cols[7]?.trim() || '',
            estoqueMarsil: parseInt(cols[8]) || 0,
            estoqueBoraceia: parseInt(cols[9]) || 0,
          };
        });

        onUploadData(parsedProducts);
        onRegisterUpdate({
          id: Date.now().toString(),
          timestamp: new Date().toISOString(),
          fileName: file.name,
          recordCount: parsedProducts.length,
          status: 'success'
        });

        setUploadStatus(`Sucesso! ${parsedProducts.length} itens carregados.`);
        setTimeout(() => setUploadStatus(null), 3000);
      } catch (err) {
        setUploadStatus('Erro ao processar arquivo. Verifique o formato.');
        onRegisterUpdate({
          id: Date.now().toString(),
          timestamp: new Date().toISOString(),
          fileName: file.name,
          recordCount: 0,
          status: 'error',
          errorMessage: 'Erro ao processar arquivo'
        });
      }
    };
    reader.readAsText(file);
  };

  const totalMarsil = appState.products.reduce((acc, p) => acc + p.estoqueMarsil, 0);
  const totalRequests = appState.requests.length;
  const pendingRequests = appState.requests.filter(r => r.status === 'Pendente').length;

  return (
    <div className="space-y-8 max-w-6xl mx-auto">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <StatsCard label="Produtos na Base" value={appState.products.length} icon={<Database />} color="bg-blue-600" />
        <StatsCard label="Total Solicitações" value={totalRequests} icon={<FileText />} color="bg-purple-600" />
        <StatsCard label="Pendentes" value={pendingRequests} icon={<ListChecks />} color="bg-amber-600" />
        <StatsCard label="Usuários Ativos" value={new Set(appState.requests.map(r => r.solicitante)).size} icon={<Users />} color="bg-emerald-600" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left Column: Upload and History */}
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
            <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
              <Upload className="w-5 h-5 text-blue-600" />
              Atualizar Base de Dados
            </h3>
            <p className="text-sm text-gray-500 mb-6">
              Faça o upload da planilha diária (CSV) para atualizar os níveis de estoque globais.
            </p>

            <label 
              className={`border-2 border-dashed rounded-xl p-8 flex flex-col items-center justify-center transition-all cursor-pointer ${
                dragActive ? 'border-blue-500 bg-blue-50' : 'border-gray-200 hover:border-blue-400'
              }`}
              onDragOver={(e) => { e.preventDefault(); setDragActive(true); }}
              onDragLeave={() => setDragActive(false)}
              onDrop={(e) => { e.preventDefault(); setDragActive(false); handleFileUpload(e); }}
            >
              <Upload className="w-10 h-10 text-gray-300 mb-3" />
              <p className="text-sm font-medium text-gray-600">Arraste a planilha ou clique aqui</p>
              <p className="text-xs text-gray-400 mt-1">Formato suportado: CSV</p>
              <input type="file" className="hidden" accept=".csv" onChange={handleFileUpload} />
            </label>

            {uploadStatus && (
              <div className={`mt-4 p-3 rounded-lg text-sm text-center font-medium ${
                uploadStatus.includes('Erro') ? 'bg-red-50 text-red-600' : 'bg-green-50 text-green-600'
              }`}>
                {uploadStatus}
              </div>
            )}
          </div>

          {/* History Section */}
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
            <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
              <History className="w-5 h-5 text-purple-600" />
              Histórico de Importações
            </h3>
            <div className="space-y-4 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar">
              {appState.updateHistory && appState.updateHistory.length > 0 ? (
                appState.updateHistory.slice(0, 10).map(log => (
                  <div key={log.id} className="flex items-start gap-3 text-sm border-b border-gray-50 last:border-0 pb-3 last:pb-0">
                    <div className="mt-0.5">
                      {log.status === 'success' ? (
                        <CheckCircle2 className="w-4 h-4 text-green-500" />
                      ) : (
                        <AlertCircle className="w-4 h-4 text-red-500" />
                      )}
                    </div>
                    <div className="flex-1">
                      <div className="flex justify-between items-start">
                        <p className="font-medium text-gray-800 line-clamp-1 break-all">{log.fileName}</p>
                        <span className="text-[10px] text-gray-400 whitespace-nowrap ml-2">
                          {new Date(log.timestamp).toLocaleDateString(undefined, { day: '2-digit', month: '2-digit' })}
                        </span>
                      </div>
                      <p className="text-xs text-gray-500 mb-0.5">
                        {new Date(log.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </p>
                      {log.status === 'success' ? (
                        <p className="text-xs text-green-600 font-medium bg-green-50 inline-block px-1.5 py-0.5 rounded">
                          {log.recordCount} itens
                        </p>
                      ) : (
                        <p className="text-xs text-red-600 font-medium bg-red-50 inline-block px-1.5 py-0.5 rounded">
                          Falha
                        </p>
                      )}
                    </div>
                  </div>
                ))
              ) : (
                <div className="text-center py-6">
                  <p className="text-gray-400 text-sm italic">Nenhum histórico disponível.</p>
                </div>
              )}
            </div>
          </div>

          <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
            <h3 className="text-lg font-bold mb-4 flex items-center gap-2 text-red-600">
              <Trash2 className="w-5 h-5" />
              Limpeza de Dados
            </h3>
            <button 
              onClick={onClearRequests}
              className="w-full py-2 border border-red-200 text-red-600 rounded-lg hover:bg-red-50 transition-colors text-sm font-semibold"
            >
              Zerar Histórico de Solicitações
            </button>
          </div>
        </div>

        {/* Requests List */}
        <div className="lg:col-span-2">
          <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
            <div className="p-6 border-b border-gray-50 flex justify-between items-center">
              <h3 className="text-lg font-bold flex items-center gap-2">
                <ListChecks className="w-5 h-5 text-blue-600" />
                Solicitações Recentes
              </h3>
              <span className="text-xs font-medium bg-blue-50 text-blue-600 px-2.5 py-1 rounded-full uppercase">
                {appState.requests.length} total
              </span>
            </div>

            <div className="overflow-x-auto">
              {appState.requests.length === 0 ? (
                <div className="p-12 text-center text-gray-400">
                  <FileText className="w-12 h-12 mx-auto mb-3 opacity-20" />
                  <p>Nenhuma solicitação pendente.</p>
                </div>
              ) : (
                <table className="w-full">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Solicitante</th>
                      <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Produto</th>
                      <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-wider text-center">Quant.</th>
                      <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-wider text-center">Tipo</th>
                      <th className="px-6 py-4 text-right text-xs font-bold text-gray-500 uppercase tracking-wider">Ações</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {appState.requests.map(req => (
                      <tr key={req.id} className="hover:bg-gray-50 transition-colors">
                        <td className="px-6 py-4 whitespace-nowrap">
                          <div className="flex items-center gap-3">
                            <div className="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold text-xs">
                              {req.solicitante.charAt(0).toUpperCase()}
                            </div>
                            <div>
                              <p className="text-sm font-semibold text-gray-900">{req.solicitante}</p>
                              <p className="text-xs text-gray-400">{new Date(req.dataSolicitacao).toLocaleDateString()}</p>
                            </div>
                          </div>
                        </td>
                        <td className="px-6 py-4">
                          <p className="text-sm text-gray-900 font-medium line-clamp-1">{req.productName}</p>
                          <p className="text-xs text-gray-400">{req.productCode}</p>
                        </td>
                        <td className="px-6 py-4 text-center">
                          <span className="text-sm font-bold text-gray-900">{req.quantidade}</span>
                        </td>
                        <td className="px-6 py-4 text-center">
                          <span className={`text-[10px] font-bold px-2 py-1 rounded-full uppercase ${
                            req.tipo === 'Teste' ? 'bg-purple-50 text-purple-600' : 'bg-blue-50 text-blue-600'
                          }`}>
                            {req.tipo}
                          </span>
                        </td>
                        <td className="px-6 py-4 text-right">
                          {req.status === 'Pendente' ? (
                            <div className="flex justify-end gap-2">
                              <button 
                                onClick={() => onUpdateRequestStatus(req.id, 'Aprovado')}
                                className="p-2 text-green-600 hover:bg-green-50 rounded-lg transition-colors"
                                title="Aprovar"
                              >
                                <CheckCircle className="w-5 h-5" />
                              </button>
                              <button 
                                onClick={() => onUpdateRequestStatus(req.id, 'Recusado')}
                                className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                title="Recusar"
                              >
                                <XCircle className="w-5 h-5" />
                              </button>
                            </div>
                          ) : (
                            <span className={`text-xs font-bold ${
                              req.status === 'Aprovado' ? 'text-green-600' : 'text-red-600'
                            }`}>
                              {req.status}
                            </span>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useCallback } from 'react';
import { Search, ShoppingCart, Calendar, RefreshCw, AlertTriangle, Building2, Store, ListPlus, X, Send, User, Hash, FileText, Filter, Copy, Check, Clock, History, Clipboard, ArrowRight, PlusCircle, CheckCircle2, Candy, Trash2, Edit3, MessageSquareText, Timer, Info } from 'lucide-react';
import { Product, StockRequest, WhatsAppConfig, RequestType, UnitType } from '../types';

interface UserPortalProps {
  products: Product[];
  requests: StockRequest[];
  vendedores: string[];
  whatsappConfig: WhatsAppConfig;
  onSubmitRequest: (req: StockRequest) => void;
  onDeleteRequest: (id: string) => void;
  onClearUserRequests: (solicitante: string) => void;
  onUpdateRequest: (req: StockRequest) => void;
}

const UNIT_OPTIONS: UnitType[] = ['UN', 'CX', 'DP', 'PCT', 'PT', 'SC', 'FD'];

export const UserPortal: React.FC<UserPortalProps> = ({ 
  products, 
  requests, 
  vendedores, 
  whatsappConfig, 
  onSubmitRequest,
  onDeleteRequest,
  onClearUserRequests,
  onUpdateRequest
}) => {
  const [activeView, setActiveView] = useState<'consulta' | 'historico'>('consulta');
  const [filterCodigo, setFilterCodigo] = useState('');
  const [filterDescricao, setFilterDescricao] = useState('');
  const [filterFornecedor, setFilterFornecedor] = useState('');

  const [selected, setSelected] = useState<Product | null>(null);
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);
  const [copySuccess, setCopySuccess] = useState<string | null>(null);
  const [requestStatus, setRequestStatus] = useState<'idle' | 'success'>('idle');

  // Request Form States
  const [quant, setQuant] = useState<number>(1);
  const [unit, setUnit] = useState<UnitType>('CX');
  const [type, setType] = useState<RequestType>('Aposta na Venda');
  const [solicitante, setSolicitante] = useState(() => {
    return '';
  });
  const [observacoes, setObservacoes] = useState('');
  const [isValidadeCurta, setIsValidadeCurta] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Filtro Combinado
  const filteredProducts = useMemo(() => {
    const cod = filterCodigo.toLowerCase().trim();
    const desc = filterDescricao.toLowerCase().trim();
    const forn = filterFornecedor.toLowerCase().trim();

    if (!cod && !desc && !forn) return [];

    return products.filter(p => {
      const matchCod = !cod || String(p.codigo).toLowerCase().includes(cod);
      const matchDesc = !desc || p.produto.toLowerCase().includes(desc);
      const matchForn = !forn || p.fornecedor.toLowerCase().includes(forn);
      return matchCod && matchDesc && matchForn;
    }).slice(0, 40);
  }, [products, filterCodigo, filterDescricao, filterFornecedor]);

  // Histórico filtrado pelo solicitante atual
  const myRequests = useMemo(() => {
    if (!solicitante) return [];
    return requests.filter(r => r.solicitante === solicitante);
  }, [requests, solicitante]);

  const handleCopy = (text: string, id: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopySuccess(id);
      setTimeout(() => setCopySuccess(null), 2000);
    });
  };

  const handleCopyFormattedList = () => {
    const dateStr = new Date().toLocaleDateString('pt-BR');
    // Adicionado o label "UNIDADE:" após a quantidade no mapeamento do texto
    const itemsStr = myRequests.map(r => 
      `QTD: ${r.quantidade} UNIDADE: ${r.unidade} - Cód: ${r.productCode}${r.productSabor ? ` (${r.productSabor})` : ''}${r.isValidadeCurta ? ' [VALIDADE CURTA]' : ''}${r.observacoes ? ` [Obs: ${r.observacoes}]` : ''}`
    ).join('\n');

    const fullText = `📦 PEDIDO MARSIL
📅 Data do Pedido: ${dateStr}
👤 Vendedor: ${solicitante || 'Não Identificado'}

${itemsStr}

Pedido Extra Boracéia`;

    handleCopy(fullText, 'hist-all');
  };

  const handleClearCart = () => {
    if (window.confirm('Deseja realmente excluir TODOS os itens do seu pedido atual?')) {
      onClearUserRequests(solicitante);
    }
  };

  const handleEditRequest = (req: StockRequest) => {
    const product = products.find(p => String(p.id) === String(req.productId) || String(p.codigo) === String(req.productCode));
    if (product) {
      setSelected(product);
      setEditingRequestId(req.id);
      setQuant(req.quantidade);
      setUnit(req.unidade);
      setType(req.tipo);
      setSolicitante(req.solicitante);
      setObservacoes(req.observacoes || '');
      setIsValidadeCurta(req.isValidadeCurta || false);
    }
  };

  const handleSendRequest = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selected || !solicitante) return;
    setIsSubmitting(true);

    if (editingRequestId) {
      const originalReq = requests.find(r => String(r.id) === String(editingRequestId));
      if (originalReq) {
        const updatedReq: StockRequest = {
          ...originalReq,
          quantidade: quant,
          unidade: unit,
          tipo: type,
          solicitante: solicitante,
          observacoes: observacoes,
          isValidadeCurta: isValidadeCurta,
          productSabor: selected.sabor || ''
        };
        onUpdateRequest(updatedReq);
      }
    } else {
      const newReq: StockRequest = {
        id: `req-${Date.now()}`,
        productId: selected.id,
        productName: selected.produto,
        productCode: String(selected.codigo),
        productSabor: selected.sabor || '',
        quantidade: quant,
        unidade: unit,
        tipo: type,
        solicitante: solicitante,
        observacoes: observacoes,
        isValidadeCurta: isValidadeCurta,
        dataSolicitacao: new Date().toISOString(),
        status: 'Pendente'
      };
      onSubmitRequest(newReq);
    }

    setRequestStatus('success');

    setTimeout(() => {
      setIsSubmitting(false);
      setSelected(null);
      setEditingRequestId(null);
      setRequestStatus('idle');
      setQuant(1);
      setObservacoes('');
      setIsValidadeCurta(false);
    }, 1200);
  };

  const getStatusColor = (status: string) => {
    const s = status.toLowerCase();
    if (s.includes('disponível') || s.includes('ativo') || s.includes('estoque')) return 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400';
    if (s.includes('falta') || s.includes('esgotado') || s.includes('inativo')) return 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400';
    if (s.includes('chegando') || s.includes('pedido') || s.includes('trânsito')) return 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400';
    return 'bg-gray-100 text-gray-700 dark:bg-slate-800 dark:text-gray-400';
  };

  const hasFilters = filterCodigo || filterDescricao || filterFornecedor;

  return (
    <div className="max-w-4xl w-full mx-auto space-y-6 animate-in fade-in duration-500">
      <div className={`p-6 rounded-3xl transition-all duration-500 border ${!solicitante ? 'bg-blue-600 border-blue-500 shadow-2xl shadow-blue-500/20 text-white' : 'bg-white dark:bg-slate-900 border-gray-100 dark:border-slate-800 shadow-sm'}`}>
        <div className="flex flex-col sm:flex-row items-center gap-6">
          <div className="flex-grow space-y-2">
            <h3 className={`text-base font-black uppercase tracking-widest flex items-center gap-2 ${!solicitante ? 'text-white' : 'dark:text-white'}`}>
              <User className={`w-5 h-5 ${!solicitante ? 'text-blue-100' : 'text-blue-500'}`} /> 
              Vendedor Responsável
            </h3>
            <p className={`text-[10px] font-bold uppercase ${!solicitante ? 'text-blue-100' : 'text-gray-400'}`}>
              {!solicitante ? 'Selecione sua identificação para começar a consulta' : 'Operando como ' + solicitante}
            </p>
          </div>

          <div className="relative group w-full sm:w-80">
            <select 
              className={`w-full pl-5 pr-10 py-4 rounded-2xl outline-none text-[11px] font-black uppercase tracking-wider shadow-sm transition-all appearance-none cursor-pointer border-2 ${!solicitante ? 'bg-white text-blue-600 border-white' : 'bg-gray-50 dark:bg-slate-800 dark:text-white border-transparent focus:border-blue-500'}`}
              value={solicitante}
              onChange={(e) => setSolicitante(e.target.value)}
            >
              <option value="" disabled>Selecione um Vendedor...</option>
              {vendedores.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
            <div className={`absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none ${!solicitante ? 'text-blue-600' : 'text-gray-400'}`}>
              <ArrowRight className="w-3 h-3 rotate-90" />
            </div>
          </div>
        </div>
      </div>

      <div className="flex bg-white dark:bg-slate-900 p-1.5 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800 w-fit mx-auto sm:mx-0">
        <button 
          onClick={() => setActiveView('consulta')}
          className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeView === 'consulta' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-gray-400 hover:text-blue-500'}`}
        >
          <Search className="w-3.5 h-3.5" /> Consulta de Itens
        </button>
        <button 
          onClick={() => setActiveView('historico')}
          className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeView === 'historico' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-gray-400 hover:text-blue-500'}`}
        >
          <History className="w-3.5 h-3.5" /> Meu Carrinho ({myRequests.length})
        </button>
      </div>

      {activeView === 'consulta' ? (
        <div className={`space-y-6 transition-opacity duration-300 ${!solicitante ? 'opacity-40 pointer-events-none grayscale' : 'opacity-100'}`}>
          <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-xl border border-gray-100 dark:border-slate-800">
            <div className="flex justify-between items-end mb-6">
              <div>
                <h2 className="text-base font-black flex items-center gap-2 uppercase tracking-widest dark:text-white mb-1">
                  <Filter className="w-5 h-5 text-blue-600" /> Pesquisa Avançada
                </h2>
                <p className="text-[10px] text-gray-400 font-bold uppercase">Busca por Código, Descrição ou Fabricante</p>
              </div>
              {hasFilters && (
                <button onClick={() => { setFilterCodigo(''); setFilterDescricao(''); setFilterFornecedor(''); }} className="text-[10px] font-black text-red-500 uppercase hover:underline flex items-center gap-1 pb-1">
                  <X className="w-3 h-3" /> Limpar Filtros
                </button>
              )}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <div className="relative group">
                <Hash className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-300 group-focus-within:text-blue-500 transition-colors" />
                <input type="text" placeholder="Código Item" className="w-full pl-11 pr-4 py-4 rounded-2xl border border-gray-100 dark:border-slate-800 bg-gray-50 dark:bg-slate-800 outline-none text-xs font-bold dark:text-white focus:ring-2 focus:ring-blue-500/20 transition-all" value={filterCodigo} onChange={(e) => setFilterCodigo(e.target.value)} />
              </div>
              <div className="relative group">
                <FileText className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-300 group-focus-within:text-blue-500 transition-colors" />
                <input type="text" placeholder="Nome / Descrição" className="w-full pl-11 pr-4 py-4 rounded-2xl border border-gray-100 dark:border-slate-800 bg-gray-50 dark:bg-slate-800 outline-none text-xs font-bold dark:text-white focus:ring-2 focus:ring-blue-500/20 transition-all" value={filterDescricao} onChange={(e) => setFilterDescricao(e.target.value)} />
              </div>
              <div className="relative group">
                <Building2 className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-300 group-focus-within:text-blue-500 transition-colors" />
                <input type="text" placeholder="Fornecedor" className="w-full pl-11 pr-4 py-4 rounded-2xl border border-gray-100 dark:border-slate-800 bg-gray-50 dark:bg-slate-800 outline-none text-xs font-bold dark:text-white focus:ring-2 focus:ring-blue-500/20 transition-all" value={filterFornecedor} onChange={(e) => setFilterFornecedor(e.target.value)} />
              </div>
            </div>

            <div className="mt-8 space-y-3 max-h-[500px] overflow-y-auto custom-scrollbar pr-1">
              {filteredProducts.map(p => (
                <div key={p.id} className={`group w-full p-5 rounded-3xl border flex flex-col sm:flex-row sm:items-center justify-between gap-4 transition-all ${selected?.id === p.id ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20 ring-2 ring-blue-500/20' : 'border-gray-50 dark:border-slate-800 hover:bg-gray-50 dark:hover:bg-slate-800/60'}`}>
                  <div className="text-left flex-grow">
                    <div className="flex items-center gap-2 mb-2">
                      <div className="flex items-center bg-blue-600 text-white px-2 py-0.5 rounded-full">
                        <span className="text-[9px] font-black flex items-center gap-1 mr-2"><Hash className="w-2.5 h-2.5" /> {p.codigo}</span>
                        <button onClick={(e) => { e.stopPropagation(); handleCopy(p.codigo, `p-cod-${p.id}`); }} className="hover:text-blue-200 transition-colors">
                          {copySuccess === `p-cod-${p.id}` ? <Check className="w-2.5 h-2.5" /> : <Copy className="w-2.5 h-2.5" />}
                        </button>
                      </div>
                      {p.situacao && (
                        <span className={`text-[9px] px-2 py-0.5 rounded-full font-black uppercase ${getStatusColor(p.situacao)}`}>
                          {p.situacao}
                        </span>
                      )}
                    </div>
                    <p className="text-sm font-black uppercase line-clamp-2 dark:text-white leading-tight mb-2 group-hover:text-blue-600 transition-colors">{p.produto}</p>
                    <div className="flex flex-wrap items-center gap-4">
                      <span className="text-[10px] text-gray-500 dark:text-gray-400 font-bold uppercase flex items-center gap-1">
                        <Building2 className="w-3 h-3 text-blue-500" /> {p.fornecedor}
                      </span>
                      {p.sabor && (
                        <span className="text-[10px] text-pink-500 dark:text-pink-400 font-bold uppercase flex items-center gap-1">
                          <Candy className="w-3 h-3" /> {p.sabor}
                        </span>
                      )}
                    </div>
                  </div>

                  <div className="flex justify-between sm:justify-end gap-6 border-t sm:border-t-0 pt-4 sm:pt-0 dark:border-slate-800 items-center">
                    <div className="flex gap-4 mr-2">
                      <div className="text-right">
                        <p className="text-base font-black dark:text-white leading-none">{p.estoqueMarsil}</p>
                        <p className="text-[8px] font-black uppercase text-gray-400 mt-1">Marsil</p>
                      </div>
                      <div className="text-right">
                        <p className="text-base font-black text-emerald-600 leading-none">{p.estoqueBoraceia}</p>
                        <p className="text-[8px] font-black uppercase text-gray-400 mt-1">Boracéia</p>
                      </div>
                    </div>
                    <button 
                      type="button"
                      disabled={!solicitante}
                      onClick={() => {
                        setEditingRequestId(null);
                        setSelected(p);
                        setQuant(1);
                        setUnit('CX');
                        setType('Aposta na Venda');
                        setObservacoes('');
                        setIsValidadeCurta(false);
                      }} 
                      className="flex items-center gap-2 px-6 py-3.5 bg-blue-600 hover:bg-blue-700 disabled:bg-gray-200 dark:disabled:bg-slate-800 text-white rounded-2xl shadow-xl shadow-blue-500/30 active:scale-95 transition-all text-[11px] font-black uppercase tracking-widest disabled:shadow-none"
                    >
                      <ShoppingCart className="w-4 h-4" /> Solicitar
                    </button>
                  </div>
                </div>
              ))}

              {!hasFilters && (
                <div className="text-center py-32 opacity-20 flex flex-col items-center">
                  <Search className="w-16 h-16 mb-4" />
                  <p className="text-xs font-black uppercase tracking-widest">Utilize os filtros acima para pesquisar o catálogo</p>
                </div>
              )}
            </div>
          </div>
        </div>
      ) : (
        <div className="bg-white dark:bg-slate-900 rounded-3xl shadow-xl border border-gray-100 dark:border-slate-800 overflow-hidden animate-in slide-in-from-right-4">
          <div className="p-6 border-b border-gray-50 dark:border-slate-800 flex flex-col sm:flex-row justify-between items-center bg-gray-50/20 dark:bg-slate-800/20 gap-4">
            <div>
              <h3 className="text-sm font-black dark:text-white uppercase tracking-wider flex items-center gap-2">
                <History className="w-4 h-4 text-blue-500" /> Histórico / Carrinho de Pedidos
              </h3>
              <p className="text-[9px] text-gray-400 font-bold uppercase mt-1">Vendedor Ativo: {solicitante || '---'}</p>
            </div>
            <div className="flex gap-2">
              <button 
                onClick={handleClearCart}
                disabled={myRequests.length === 0}
                className="text-[9px] font-black bg-red-50 dark:bg-red-900/30 text-red-600 px-4 py-2.5 rounded-xl uppercase flex items-center gap-2 hover:brightness-95 transition-all shadow-sm disabled:opacity-30"
              >
                <Trash2 className="w-3.5 h-3.5" />
                Limpar
              </button>
              <button 
                onClick={handleCopyFormattedList}
                disabled={myRequests.length === 0}
                className="text-[9px] font-black bg-blue-50 dark:bg-blue-900/30 text-blue-600 px-4 py-2.5 rounded-xl uppercase flex items-center gap-2 hover:brightness-95 transition-all shadow-sm disabled:opacity-30"
              >
                {copySuccess === 'hist-all' ? <Check className="w-3.5 h-3.5" /> : <Clipboard className="w-3.5 h-3.5" />}
                Copiar Lista
              </button>
            </div>
          </div>
          <div className="overflow-x-auto">
            {myRequests.length === 0 ? (
              <div className="py-24 text-center opacity-30 flex flex-col items-center">
                <Clock className="w-12 h-12 mb-4" />
                <p className="text-[10px] font-black uppercase tracking-widest">Seu carrinho de solicitações está vazio.</p>
              </div>
            ) : (
              <table className="w-full text-left border-collapse min-w-[500px]">
                <thead className="bg-gray-50/50 dark:bg-slate-800/50">
                  <tr>
                    <th className="px-6 py-4 text-[9px] font-black text-gray-400 uppercase">Item</th>
                    <th className="px-6 py-4 text-[9px] font-black text-gray-400 uppercase">Solicitação</th>
                    <th className="px-6 py-4 text-[9px] font-black text-gray-400 uppercase text-center">Ações</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50 dark:divide-slate-800">
                  {myRequests.map(req => (
                    <tr key={req.id} className="hover:bg-gray-50 dark:hover:bg-slate-800/40 transition-colors group">
                      <td className="px-6 py-4">
                        <div className="flex flex-col gap-1">
                          <div className="flex items-center gap-2">
                            <span className="text-[10px] font-black bg-blue-50 dark:bg-blue-900/30 text-blue-600 px-1.5 w-fit rounded uppercase">{req.productCode}</span>
                            {req.isValidadeCurta && (
                              <span className="text-[8px] font-black bg-orange-100 text-orange-600 dark:bg-orange-900/30 dark:text-orange-400 px-1.5 py-0.5 rounded flex items-center gap-1 uppercase">
                                <Timer className="w-2.5 h-2.5" /> Val. Curta
                              </span>
                            )}
                          </div>
                          <p className="text-[11px] font-bold dark:text-slate-200 line-clamp-1">{req.productName}</p>
                          {req.productSabor && (
                             <p className="text-[9px] font-black text-pink-500 uppercase">{req.productSabor}</p>
                          )}
                          {req.observacoes && (
                            <p className="text-[9px] text-blue-500 font-medium italic mt-0.5 max-w-xs truncate">"{req.observacoes}"</p>
                          )}
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex flex-col gap-1">
                          <span className="text-[11px] font-black text-gray-700 dark:text-slate-300 uppercase">{req.quantidade} {req.unidade}</span>
                          <span className="text-[8px] font-bold text-gray-400 uppercase">{req.tipo}</span>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex justify-center gap-3">
                          <button 
                            type="button"
                            onClick={() => handleEditRequest(req)}
                            className="flex flex-col items-center gap-1 group/btn"
                            title="Editar"
                          >
                            <div className="p-2.5 bg-blue-50 dark:bg-blue-900/20 text-blue-600 group-hover/btn:bg-blue-600 group-hover/btn:text-white rounded-xl transition-all shadow-sm">
                              <Edit3 className="w-4 h-4" />
                            </div>
                          </button>
                          <button 
                            type="button"
                            onClick={(e) => {
                              e.stopPropagation();
                              if (window.confirm('Deseja realmente excluir este item do pedido?')) {
                                onDeleteRequest(req.id);
                              }
                            }}
                            className="flex flex-col items-center gap-1 group/btn"
                            title="Excluir"
                          >
                            <div className="p-2.5 bg-red-50 dark:bg-red-900/20 text-red-600 group-hover/btn:bg-red-600 group-hover/btn:text-white rounded-xl transition-all shadow-sm">
                              <Trash2 className="w-4 h-4" />
                            </div>
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </div>
      )}

      {selected && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-sm animate-in fade-in">
          <div className="bg-white dark:bg-slate-900 w-full max-w-md rounded-3xl shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-800 animate-in zoom-in-95">
            <div className="p-6 border-b dark:border-slate-800 flex justify-between items-center bg-gray-50/50 dark:bg-slate-800/30">
              <div>
                <h3 className="text-lg font-black dark:text-white uppercase leading-tight">
                  {editingRequestId ? 'Editar Item' : 'Configurar Item'}
                </h3>
                <div className="flex items-center gap-2 mt-1">
                  <p className="text-[10px] font-bold text-blue-500 uppercase line-clamp-1">{selected.produto}</p>
                </div>
                {selected.sabor && (
                  <p className="text-[9px] font-black text-pink-500 uppercase flex items-center gap-1 mt-1">
                    <Candy className="w-2.5 h-2.5" /> Sabor: {selected.sabor}
                  </p>
                )}
              </div>
              <button onClick={() => { setSelected(null); setEditingRequestId(null); }} className="p-2 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-xl transition-colors"><X className="w-5 h-5 text-gray-400" /></button>
            </div>

            <form onSubmit={handleSendRequest} className="p-6 space-y-4 max-h-[70vh] overflow-y-auto custom-scrollbar">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black uppercase text-gray-400 px-1 flex items-center gap-1 group/tooltip relative">
                    Quantidade
                    <Info className="w-3 h-3 text-gray-300 cursor-help" />
                    <span className="invisible group-hover/tooltip:visible absolute bottom-full left-0 mb-2 w-48 p-2 bg-slate-800 text-white text-[9px] font-medium rounded-lg shadow-xl z-50 normal-case tracking-normal">
                      Informe o volume desejado baseado na unidade (UN, CX, etc).
                    </span>
                  </label>
                  <input type="number" min="1" required className="w-full px-4 py-4 bg-gray-50 dark:bg-slate-800 rounded-xl font-bold dark:text-white outline-none border-2 border-transparent focus:border-blue-500 transition-all shadow-inner" value={quant} onChange={e => setQuant(parseInt(e.target.value))} />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black uppercase text-gray-400 px-1">Unidade</label>
                  <select className="w-full px-4 py-4 bg-gray-50 dark:bg-slate-800 rounded-xl font-bold dark:text-white outline-none border-2 border-transparent focus:border-blue-500 transition-all shadow-inner" value={unit} onChange={e => setUnit(e.target.value as UnitType)}>
                    {UNIT_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
                  </select>
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-black uppercase text-gray-400 px-1 flex items-center gap-1 group/tooltip relative">
                  Natureza do Pedido
                  <Info className="w-3 h-3 text-gray-300 cursor-help" />
                  <span className="invisible group-hover/tooltip:visible absolute bottom-full left-0 mb-2 w-56 p-2 bg-slate-800 text-white text-[9px] font-medium rounded-lg shadow-xl z-50 normal-case tracking-normal">
                    Aposta: Previsão de venda futura. <br/> Garantida: Pedido para venda já realizada.
                  </span>
                </label>
                <div className="grid grid-cols-2 gap-2">
                  <button type="button" onClick={() => setType('Aposta na Venda')} className={`py-4 rounded-xl text-[10px] font-black uppercase border-2 transition-all ${type === 'Aposta na Venda' ? 'bg-blue-600 border-blue-600 text-white shadow-lg shadow-blue-500/30' : 'bg-gray-50 dark:bg-slate-800 border-transparent text-gray-400 hover:bg-gray-100'}`}>Aposta na Venda</button>
                  <button type="button" onClick={() => setType('Venda Garantida')} className={`py-4 rounded-xl text-[10px] font-black uppercase border-2 transition-all ${type === 'Venda Garantida' ? 'bg-blue-600 border-blue-600 text-white shadow-lg shadow-blue-500/30' : 'bg-gray-50 dark:bg-slate-800 border-transparent text-gray-400 hover:bg-gray-100'}`}>Venda Garantida</button>
                </div>
              </div>

              <div className="space-y-1.5 pt-2">
                <button 
                  type="button" 
                  onClick={() => setIsValidadeCurta(!isValidadeCurta)} 
                  className={`w-full flex items-center justify-between px-5 py-4 rounded-xl border-2 transition-all ${isValidadeCurta ? 'bg-orange-50 border-orange-500 text-orange-700 shadow-sm' : 'bg-gray-50 dark:bg-slate-800 border-transparent text-gray-400'}`}
                >
                  <div className="flex items-center gap-3">
                    <Timer className={`w-5 h-5 ${isValidadeCurta ? 'text-orange-500' : 'text-gray-400'}`} />
                    <span className="text-[10px] font-black uppercase tracking-widest">Validade Curta?</span>
                  </div>
                  <div className={`w-5 h-5 rounded-md border-2 flex items-center justify-center transition-colors ${isValidadeCurta ? 'bg-orange-500 border-orange-500' : 'border-gray-200 dark:border-slate-700'}`}>
                    {isValidadeCurta && <Check className="w-3 h-3 text-white stroke-[4]" />}
                  </div>
                </button>
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-black uppercase text-gray-400 px-1 flex items-center gap-1">
                  <MessageSquareText className="w-3 h-3 text-blue-500" /> Observações (Opcional)
                </label>
                <textarea 
                  placeholder="Ex: Urgente para amanhã..." 
                  className="w-full px-4 py-3 bg-gray-50 dark:bg-slate-800 rounded-xl font-medium text-xs dark:text-white outline-none border-2 border-transparent focus:border-blue-500 transition-all shadow-inner h-20 resize-none"
                  value={observacoes}
                  onChange={e => setObservacoes(e.target.value)}
                />
              </div>

              <button 
                disabled={isSubmitting || !solicitante} 
                type="submit" 
                className={`w-full font-black py-6 rounded-2xl flex items-center justify-center gap-4 uppercase text-sm tracking-[0.15em] shadow-2xl active:scale-95 transition-all mt-6 ${requestStatus === 'success' ? 'bg-emerald-500 text-white ring-4 ring-emerald-500/20' : 'bg-blue-600 hover:bg-blue-700 text-white ring-4 ring-blue-600/10'}`}
              >
                {isSubmitting ? (
                  <RefreshCw className="w-6 h-6 animate-spin" />
                ) : requestStatus === 'success' ? (
                  <><CheckCircle2 className="w-6 h-6" /> {editingRequestId ? 'ATUALIZADO!' : 'ADICIONADO!'}</>
                ) : (
                  <><PlusCircle className="w-6 h-6" /> {editingRequestId ? 'SALVAR ALTERAÇÕES' : 'ADICIONAR AO PEDIDO'}</>
                )}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export interface Product {
  id: string;
  fornecedor: string;
  codigo: string;
  situacao: string;
  comprador: string;
  produto: string;
  sabor: string;
  embalagem: string;
  estoqueMarsil: number;
  estoqueBoraceia: number;
}

export type RequestType = 'Aposta na Venda' | 'Venda Garantida';
export type UnitType = 'UN' | 'CX' | 'DP' | 'PCT' | 'PT' | 'SC' | 'FD';

export interface WhatsAppConfig {
  enabled: boolean;
  phoneNumber: string;
}

export interface UpdateLog {
  id: string;
  timestamp: string;
  fileName: string;
  recordCount: number;
  status: 'success' | 'error';
  errorMessage?: string;
}

export interface StockRequest {
  id: string;
  productId: string;
  productName: string;
  productCode: string;
  productSabor: string;
  quantidade: number;
  unidade: UnitType;
  tipo: RequestType;
  solicitante: string;
  observacoes?: string;
  isValidadeCurta: boolean;
  dataSolicitacao: string; // ISO format
  status: 'Pendente' | 'Aprovado' | 'Recusado';
}

export interface AppState {
  products: Product[];
  requests: StockRequest[];
  vendedores: string[];
  whatsappConfig: WhatsAppConfig;
  updateHistory: UpdateLog[];
}

import React, { useState, useEffect, useCallback } from 'react';
import { UserPortal } from './components/UserPortal';
import { AdminPortal } from './components/AdminPortal';
import { AppState, Product, StockRequest, WhatsAppConfig, UpdateLog } from './types';
import { LayoutDashboard, ShieldCheck, Sun, Moon, KeyRound, LogOut, ChevronRight, Store, X, Loader2 } from 'lucide-react';
import Papa from 'papaparse';

const THEME_KEY = 'marsil_theme_pref';
const AUTH_KEY = 'marsil_auth_role';
const PRODUCTS_KEY = 'marsil_local_products';
const VENDEDORES_KEY = 'marsil_vendedores_list';
const REQUESTS_KEY = 'marsil_requests_history';
const SYNC_URL_KEY = 'marsil_sync_url';
const UPDATE_HISTORY_KEY = 'marsil_update_history';

const PASSWORDS = {
  VENDOR: '@marsil2026',
  ADMIN: '@adminMarsil2026'
};

const DEFAULT_VENDEDORES = [
  "ADALTON LUIZ", "AIRTON DONIZETTI", "ANA CAMARGO", "ANA PAULA", "CARLOS ROSEIRO",
  "DOUGLAS PITELLI", "EDMILSON LEAL", "FERNANDO APARECIDO", "GUSTAVO PAULINO",
  "JOAO JOSE", "JOAO MANUEL", "LEONARDO APARECIDO", "LUIS ALEXANDRE",
  "MARCELO SANTOS", "MARCO AURELIO", "NIVALDO NEVES", "ROSIMAR FREITAS",
  "ROZIMARA SOUZA", "TELMA CRISTINA", "WASHINGTON BELMIRO", "OUTRO"
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'user' | 'admin'>('user');
  const [authRole, setAuthRole] = useState<'none' | 'vendor' | 'admin'>(() => {
    return (localStorage.getItem(AUTH_KEY) as any) || 'none';
  });

  const [loginTarget, setLoginTarget] = useState<'vendedor' | 'admin' | null>(null);
  const [passwordInput, setPasswordInput] = useState('');
  const [loginError, setLoginError] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  const [isDarkMode, setIsDarkMode] = useState(() => {
    const savedTheme = localStorage.getItem(THEME_KEY);
    return savedTheme === 'dark';
  });

  const [appState, setAppState] = useState<AppState>(() => {
    const savedProducts = localStorage.getItem(PRODUCTS_KEY);
    const savedVendedores = localStorage.getItem(VENDEDORES_KEY);
    const savedRequests = localStorage.getItem(REQUESTS_KEY);
    const savedHistory = localStorage.getItem(UPDATE_HISTORY_KEY);

    let finalVendedores = DEFAULT_VENDEDORES;
    if (savedVendedores) {
      try {
        const parsed = JSON.parse(savedVendedores);
        if (Array.isArray(parsed) && parsed.length > 0) finalVendedores = parsed;
      } catch (e) { finalVendedores = DEFAULT_VENDEDORES; }
    }

    return { 
      products: savedProducts ? JSON.parse(savedProducts) : [], 
      requests: savedRequests ? JSON.parse(savedRequests) : [], 
      vendedores: finalVendedores,
      whatsappConfig: { enabled: true, phoneNumber: '5511999999999' },
      updateHistory: savedHistory ? JSON.parse(savedHistory) : []
    };
  });

  const mapCSVData = (data: any[]) => {
    return data.map((row: any, i: number) => {
      const findVal = (keys: string[]) => {
        const key = Object.keys(row).find(k => 
          keys.some(s => k.trim().toLowerCase() === s.toLowerCase()) ||
          keys.some(s => k.trim().toLowerCase().includes(s.toLowerCase()))
        );
        return key ? String(row[key]).trim() : '';
      };

      return {
        id: `p-${i}-${Date.now()}`,
        fornecedor: findVal(['Fornecedor', 'Forn', 'Marca', 'Fabricante']),
        codigo: findVal(['Código', 'Cód', 'Ref', 'Cod Item', 'Item', 'codigo', 'ID', 'Referência']),
        situacao: findVal(['Situação', 'Status', 'Sit', 'Disponibilidade']),
        comprador: findVal(['Comprador', 'Responsável', 'Buyer']),
        produto: findVal(['Produto', 'Descrição', 'Nome', 'Desc', 'produto']),
        sabor: findVal(['Sabor', 'Gosto', 'Flavor', 'Variante']),
        embalagem: findVal(['Embalagem', 'Emb', 'Pack']),
        estoqueMarsil: parseInt(findVal(['Marsil', 'SP', 'Estoque Marsil', 'Matriz'])) || 0,
        estoqueBoraceia: parseInt(findVal(['Boraceia', 'Boracéia', 'Filial', 'Estoque Boraceia'])) || 0,
      };
    }).filter(p => p.produto && p.produto !== '');
  };

  useEffect(() => {
    const initApp = async () => {
      const params = new URLSearchParams(window.location.search);
      const urlSync = params.get('s');
      const urlVendors = params.get('v');
      let initialVendedores = appState.vendedores;

      if (urlVendors) {
        try {
          const parsed = JSON.parse(decodeURIComponent(urlVendors));
          if (Array.isArray(parsed) && parsed.length > 0) {
            initialVendedores = parsed;
            localStorage.setItem(VENDEDORES_KEY, JSON.stringify(parsed));
          }
        } catch (e) { console.error(e); }
      }

      if (urlSync) {
        localStorage.setItem(SYNC_URL_KEY, urlSync);
        Papa.parse(urlSync, {
          download: true, header: true, skipEmptyLines: true,
          complete: (results) => {
            const mapped = mapCSVData(results.data);
            setAppState(prev => ({ ...prev, products: mapped, vendedores: initialVendedores }));
            setIsLoading(false);
          },
          error: () => setIsLoading(false)
        });
      } else {
        if (urlVendors) setAppState(prev => ({ ...prev, vendedores: initialVendedores }));
        setTimeout(() => setIsLoading(false), 800);
      }
    };
    initApp();
  }, []);

  useEffect(() => { localStorage.setItem(AUTH_KEY, authRole); }, [authRole]);
  useEffect(() => {
    localStorage.setItem(PRODUCTS_KEY, JSON.stringify(appState.products));
    localStorage.setItem(VENDEDORES_KEY, JSON.stringify(appState.vendedores));
    localStorage.setItem(REQUESTS_KEY, JSON.stringify(appState.requests));
    localStorage.setItem(UPDATE_HISTORY_KEY, JSON.stringify(appState.updateHistory));
  }, [appState]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem(THEME_KEY, 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem(THEME_KEY, 'light');
    }
  }, [isDarkMode]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const requiredPass = loginTarget === 'admin' ? PASSWORDS.ADMIN : PASSWORDS.VENDOR;
    if (passwordInput === requiredPass) {
      const role = loginTarget === 'admin' ? 'admin' : 'vendor';
      setAuthRole(role);
      setActiveTab(loginTarget === 'admin' ? 'admin' : 'user');
      setLoginError(false);
      setLoginTarget(null);
    } else {
      setLoginError(true);
      setTimeout(() => setLoginError(false), 3000);
    }
    setPasswordInput('');
  };

  const handleLogout = () => {
    setAuthRole('none');
    setLoginTarget(null);
    setPasswordInput('');
    setActiveTab('user');
    localStorage.removeItem(AUTH_KEY);
  };

  const handleUploadData = (newProducts: Product[]) => {
    setAppState(prev => ({ ...prev, products: newProducts }));
  };

  const handleRegisterUpdate = (log: UpdateLog) => {
    setAppState(prev => ({
      ...prev,
      updateHistory: [log, ...prev.updateHistory].slice(0, 20)
    }));
  };

  const handleAddVendedor = (name: string) => {
    if (!appState.vendedores.includes(name)) {
      setAppState(prev => ({ ...prev, vendedores: [...prev.vendedores, name].sort() }));
    }
  };

  const handleRemoveVendedor = (name: string) => {
    setAppState(prev => ({ ...prev, vendedores: prev.vendedores.filter(v => v !== name) }));
  };

  const handleUpdateWhatsApp = (config: WhatsAppConfig) => {
    setAppState(prev => ({ ...prev, whatsappConfig: config }));
  };

  const handleSubmitRequest = (request: StockRequest) => {
    setAppState(prev => ({ ...prev, requests: [request, ...prev.requests] }));
  };

  const handleUpdateRequest = (updatedRequest: StockRequest) => {
    setAppState(prev => ({
      ...prev,
      requests: prev.requests.map(r => String(r.id) === String(updatedRequest.id) ? updatedRequest : r)
    }));
  };

  const handleDeleteRequest = useCallback((requestId: string) => {
    setAppState(prev => ({ ...prev, requests: prev.requests.filter(r => String(r.id) !== String(requestId)) }));
  }, []);

  const handleClearUserRequests = useCallback((solicitante: string) => {
    setAppState(prev => ({ ...prev, requests: prev.requests.filter(r => r.solicitante !== solicitante) }));
  }, []);

  const handleUpdateRequestStatus = (requestId: string, status: StockRequest['status']) => {
    setAppState(prev => ({
      ...prev,
      requests: prev.requests.map(r => String(r.id) === String(requestId) ? { ...r, status } : r)
    }));
  };

  const handleClearRequests = () => {
    if (window.confirm('Limpar histórico local de pedidos?')) {
      setAppState(prev => ({ ...prev, requests: [] }));
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-slate-950">
        <div className="flex flex-col items-center gap-4">
          <Loader2 className="w-8 h-8 text-blue-600 animate-spin" />
          <p className="text-[10px] font-black uppercase tracking-widest text-gray-400">Carregando Marsil</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-slate-950 text-gray-900 dark:text-slate-100 transition-colors duration-300">
      <header className="bg-white dark:bg-slate-900 border-b border-gray-200 dark:border-slate-800 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <div className="bg-blue-600 p-2 rounded-xl shrink-0">
                <LayoutDashboard className="w-5 h-5 text-white" />
              </div>
              <div className="flex flex-col">
                <h1 className="text-lg font-black tracking-tight dark:text-white">Marsil & Boracéia</h1>
                <p className="text-[9px] text-gray-400 font-bold uppercase tracking-tighter">Gestão de Estoque</p>
              </div>
            </div>
            <div className="flex items-center gap-4">
              <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-gray-400 hover:text-blue-500 transition-colors">
                {isDarkMode ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
              </button>
              {authRole !== 'none' && (
                <div className="flex items-center gap-2">
                  <div className="bg-gray-100 dark:bg-slate-800 p-1 rounded-xl flex">
                    <button onClick={() => setActiveTab('user')} className={`px-3 py-1.5 text-[10px] font-black rounded-lg uppercase ${activeTab === 'user' ? 'bg-white dark:bg-slate-700 text-blue-600 shadow-sm' : 'text-gray-400'}`}>Consulta</button>
                    {authRole === 'admin' && (
                      <button onClick={() => setActiveTab('admin')} className={`px-3 py-1.5 text-[10px] font-black rounded-lg uppercase ${activeTab === 'admin' ? 'bg-white dark:bg-slate-700 text-blue-600 shadow-sm' : 'text-gray-400'}`}>Admin</button>
                    )}
                  </div>
                  <button onClick={handleLogout} className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-xl transition-colors"><LogOut className="w-4 h-4" /></button>
                </div>
              )}
            </div>
          </div>
        </div>
      </header>
      <main className="flex-grow p-4 sm:p-8 flex flex-col items-center">
        {authRole === 'none' ? (
          !loginTarget ? (
            <div className="w-full max-w-2xl mt-12 animate-in fade-in zoom-in-95 duration-500 space-y-8">
              <div className="text-center space-y-2">
                <h2 className="text-4xl font-black dark:text-white tracking-tight">Painel de Estoque</h2>
                <p className="text-gray-500 dark:text-slate-400 text-sm">Acesse para consultar itens e realizar pedidos.</p>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <button onClick={() => setLoginTarget('vendedor')} className="group bg-white dark:bg-slate-900 p-8 rounded-3xl shadow-xl hover:shadow-2xl border-2 border-transparent hover:border-emerald-500 transition-all flex flex-col items-center space-y-4">
                  <div className="w-16 h-16 bg-emerald-50 dark:bg-emerald-900/30 rounded-2xl flex items-center justify-center group-hover:bg-emerald-600 group-hover:text-white transition-all">
                    <Store className="w-8 h-8 text-emerald-600 group-hover:text-white" />
                  </div>
                  <h3 className="text-xl font-bold dark:text-white">Vendedor</h3>
                  <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Acessar <ChevronRight className="w-4 h-4 inline" /></p>
                </button>
                <button onClick={() => setLoginTarget('admin')} className="group bg-white dark:bg-slate-900 p-8 rounded-3xl shadow-xl hover:shadow-2xl border-2 border-transparent hover:border-blue-500 transition-all flex flex-col items-center space-y-4">
                  <div className="w-16 h-16 bg-blue-50 dark:bg-blue-900/30 rounded-2xl flex items-center justify-center group-hover:bg-blue-600 group-hover:text-white transition-all">
                    <ShieldCheck className="w-8 h-8 text-blue-600 group-hover:text-white" />
                  </div>
                  <h3 className="text-xl font-bold dark:text-white">Administrador</h3>
                  <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Configurar <ChevronRight className="w-4 h-4 inline" /></p>
                </button>
              </div>
            </div>
          ) : (
            <div className="w-full max-w-sm mt-12 animate-in slide-in-from-bottom-8 duration-500 px-4">
              <div className="bg-white dark:bg-slate-900 p-8 rounded-3xl shadow-2xl border border-gray-100 dark:border-slate-800 text-center relative">
                <button onClick={() => setLoginTarget(null)} className="absolute left-4 top-4 p-2 text-gray-400 hover:text-gray-600 transition-colors"><X className="w-4 h-4" /></button>
                <div className={`w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-6 ${loginTarget === 'admin' ? 'bg-blue-50 dark:bg-blue-900/30' : 'bg-emerald-50 dark:bg-emerald-900/30'}`}>
                  {loginTarget === 'admin' ? <ShieldCheck className="w-8 h-8 text-blue-600" /> : <Store className="w-8 h-8 text-emerald-600" />}
                </div>
                <h2 className="text-2xl font-black dark:text-white mb-6">Login {loginTarget === 'admin' ? 'Admin' : 'Vendedor'}</h2>
                <form onSubmit={handleLogin} className="space-y-4">
                  <div className="relative">
                    <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                    <input autoFocus type="password" placeholder="Sua senha..." value={passwordInput} onChange={(e) => setPasswordInput(e.target.value)} className="w-full pl-12 pr-4 py-4 rounded-2xl border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 outline-none transition-all dark:text-white font-bold" />
                  </div>
                  {loginError && <p className="text-[10px] text-red-500 font-bold uppercase">Senha incorreta!</p>}
                  <button type="submit" className="w-full bg-blue-600 text-white font-black py-4 rounded-2xl shadow-lg active:scale-95 transition-all uppercase tracking-widest text-xs">Entrar</button>
                </form>
              </div>
            </div>
          )
        ) : (
          activeTab === 'user' ? (
            <UserPortal 
              products={appState.products} 
              requests={appState.requests} 
              vendedores={appState.vendedores} 
              whatsappConfig={appState.whatsappConfig} 
              onSubmitRequest={handleSubmitRequest}
              onDeleteRequest={handleDeleteRequest}
              onClearUserRequests={handleClearUserRequests}
              onUpdateRequest={handleUpdateRequest}
            />
          ) : (
            <AdminPortal 
              appState={appState} 
              onUploadData={handleUploadData} 
              onRegisterUpdate={handleRegisterUpdate}
              onAddVendedor={handleAddVendedor} 
              onRemoveVendedor={handleRemoveVendedor} 
              onUpdateWhatsApp={handleUpdateWhatsApp} 
              onUpdateRequestStatus={handleUpdateRequestStatus} 
              onClearRequests={handleClearRequests} 
            />
          )
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Upload, Database, FileText, CheckCircle, XCircle, Users, UserPlus, X, Globe, ArrowDownToLine, RefreshCw, AlertCircle, Phone, Info, Clock, Check, Trash2, Share2, ClipboardList, Send, MessageSquareText, Timer, History, CheckCircle2 } from 'lucide-react';
import { Product, StockRequest, AppState, WhatsAppConfig, UpdateLog } from '../types';
import { StatsCard } from './StatsCard';
import Papa from 'papaparse';

interface AdminPortalProps {
  appState: AppState;
  onUploadData: (newProducts: Product[]) => void;
  onRegisterUpdate: (log: UpdateLog) => void;
  onAddVendedor: (name: string) => void;
  onRemoveVendedor: (name: string) => void;
  onUpdateWhatsApp: (config: WhatsAppConfig) => void;
  onUpdateRequestStatus: (requestId: string, status: StockRequest['status']) => void;
  onClearRequests: () => void;
}

export const AdminPortal: React.FC<AdminPortalProps> = ({ 
  appState, 
  onUploadData, 
  onRegisterUpdate,
  onAddVendedor,
  onRemoveVendedor,
  onUpdateWhatsApp,
  onUpdateRequestStatus,
  onClearRequests
}) => {
  const [uploadStatus, setUploadStatus] = useState<{message: string, type: 'success' | 'error' | 'info'} | null>(null);
  const [newVendedor, setNewVendedor] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncUrl, setSyncUrl] = useState(() => localStorage.getItem('marsil_sync_url') || '');
  const [waNumber, setWaNumber] = useState(appState.whatsappConfig.phoneNumber);
  const [copied, setCopied] = useState(false);
  const [pasteContent, setPasteContent] = useState('');

  const mapData = (data: any[]) => {
    return data.map((row: any, i: number) => {
      const findVal = (keys: string[]) => {
        const key = Object.keys(row).find(k => 
          keys.some(s => k.trim().toLowerCase() === s.toLowerCase()) ||
          keys.some(s => k.trim().toLowerCase().includes(s.toLowerCase()))
        );
        return key ? String(row[key]).trim() : '';
      };

      return {
        id: `p-${i}-${Date.now()}`,
        fornecedor: findVal(['Fornecedor', 'Forn', 'Marca', 'Fabricante']),
        codigo: findVal(['Código', 'Cód', 'Ref', 'Cod Item', 'Item', 'codigo', 'ID', 'Referência']),
        situacao: findVal(['Situação', 'Status', 'Sit', 'Disponibilidade']),
        comprador: findVal(['Comprador', 'Responsável', 'Buyer']),
        produto: findVal(['Produto', 'Descrição', 'Nome', 'Desc', 'produto']),
        sabor: findVal(['Sabor', 'Gosto', 'Flavor', 'Variante']),
        embalagem: findVal(['Embalagem', 'Emb', 'Pack']),
        estoqueMarsil: parseInt(findVal(['Marsil', 'SP', 'Estoque Marsil', 'Matriz'])) || 0,
        estoqueBoraceia: parseInt(findVal(['Boraceia', 'Boracéia', 'Filial', 'Estoque Boraceia'])) || 0,
      };
    }).filter(p => p.produto && p.produto !== '');
  };

  const processData = (content: string, source: string) => {
    Papa.parse(content, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        const mapped = mapData(results.data);
        if (mapped.length === 0) {
          setUploadStatus({ message: 'Nenhum dado válido encontrado.', type: 'error' });
          onRegisterUpdate({ id: Date.now().toString(), timestamp: new Date().toISOString(), fileName: source, recordCount: 0, status: 'error', errorMessage: 'Nenhum dado válido' });
          return;
        }
        onUploadData(mapped);
        onRegisterUpdate({ id: Date.now().toString(), timestamp: new Date().toISOString(), fileName: source, recordCount: mapped.length, status: 'success' });
        setUploadStatus({ message: `Sucesso! ${mapped.length} itens carregados.`, type: 'success' });
        setPasteContent('');
        setTimeout(() => setUploadStatus(null), 5000);
      },
      error: () => {
        setUploadStatus({ message: 'Erro ao processar dados.', type: 'error' });
        onRegisterUpdate({ id: Date.now().toString(), timestamp: new Date().toISOString(), fileName: source, recordCount: 0, status: 'error', errorMessage: 'Falha no PapaParse' });
      }
    });
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploadStatus({ message: 'Lendo arquivo...', type: 'info' });
    const reader = new FileReader();
    reader.onload = (event) => {
      processData(event.target?.result as string, file.name);
    };
    reader.readAsText(file);
  };

  const handleSyncFromUrl = async () => {
    if (!syncUrl) return;
    setIsSyncing(true);
    setUploadStatus({ message: 'Sincronizando via link...', type: 'info' });
    localStorage.setItem('marsil_sync_url', syncUrl);
    Papa.parse(syncUrl, {
      download: true, header: true, skipEmptyLines: true,
      complete: (results) => {
        const mapped = mapData(results.data);
        if (mapped.length > 0) {
          onUploadData(mapped);
          onRegisterUpdate({ id: Date.now().toString(), timestamp: new Date().toISOString(), fileName: 'Sincronização Nuvem', recordCount: mapped.length, status: 'success' });
          setUploadStatus({ message: `Sincronizado! ${mapped.length} itens atualizados.`, type: 'success' });
        } else {
          setUploadStatus({ message: 'Nenhum dado encontrado no link.', type: 'error' });
        }
        setIsSyncing(false);
        setTimeout(() => setUploadStatus(null), 5000);
      },
      error: () => {
        setUploadStatus({ message: 'Erro ao conectar.', type: 'error' });
        setIsSyncing(false);
      }
    });
  };

  const handleGenerateShareLink = () => {
    if (!syncUrl) return;
    const baseUrl = window.location.origin + window.location.pathname;
    const vendorsEncoded = encodeURIComponent(JSON.stringify(appState.vendedores));
    const shareUrl = `${baseUrl}?s=${encodeURIComponent(syncUrl)}&v=${vendorsEncoded}`;
    navigator.clipboard.writeText(shareUrl).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 3000);
    });
  };

  return (
    <div className="space-y-8 max-w-6xl w-full mx-auto pb-12 animate-in fade-in">
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <StatsCard label="Itens de Estoque" value={appState.products.length} icon={<Database className="w-4 h-4" />} color="bg-blue-600" />
        <StatsCard label="Vendedores" value={appState.vendedores.length} icon={<Users className="w-4 h-4" />} color="bg-emerald-600" />
        <StatsCard label="Solicitações" value={appState.requests.length} icon={<FileText className="w-4 h-4" />} color="bg-purple-600" />
        <div className="bg-white dark:bg-slate-900 p-5 rounded-3xl shadow-sm border border-gray-100 dark:border-slate-800 flex items-center gap-3">
          <History className="w-5 h-5 text-blue-500 shrink-0" />
          <p className="text-[10px] font-black uppercase text-gray-400 leading-tight">Os dados são armazenados localmente e atualizados conforme sua planilha.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h3 className="text-sm font-black mb-4 flex items-center gap-2 dark:text-white uppercase tracking-wider">
              <RefreshCw className="w-4 h-4 text-emerald-600" /> Sincronização Google Sheets
            </h3>
            <div className="space-y-3">
              <input type="url" placeholder="Link CSV publicado..." className="w-full px-4 py-3 rounded-xl border border-gray-100 dark:border-slate-800 bg-gray-50 dark:bg-slate-800 dark:text-white text-[11px] outline-none transition-all focus:ring-2 focus:ring-emerald-500/20" value={syncUrl} onChange={(e) => setSyncUrl(e.target.value)} />
              <div className="grid grid-cols-2 gap-2">
                <button onClick={handleSyncFromUrl} disabled={isSyncing || !syncUrl} className="bg-emerald-600 disabled:opacity-50 text-white font-black py-3 rounded-xl text-[9px] uppercase flex items-center justify-center gap-1 shadow-lg hover:brightness-110 active:scale-95 transition-all">{isSyncing ? <RefreshCw className="w-3 h-3 animate-spin" /> : <RefreshCw className="w-3 h-3" />} Sincronizar</button>
                <button onClick={handleGenerateShareLink} disabled={!syncUrl} className="bg-blue-600 disabled:opacity-50 text-white font-black py-3 rounded-xl text-[9px] uppercase flex items-center justify-center gap-1 shadow-lg hover:brightness-110 active:scale-95 transition-all">{copied ? <Check className="w-3 h-3" /> : <Share2 className="w-3 h-3" />} {copied ? 'Copiado' : 'Compartilhar'}</button>
              </div>
            </div>
          </div>

          {/* NOVO: Histórico de Atualizações */}
          <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h3 className="text-sm font-black mb-4 flex items-center gap-2 dark:text-white uppercase tracking-wider">
              <History className="w-4 h-4 text-purple-600" /> Histórico de Atualizações
            </h3>
            <div className="space-y-3 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar">
              {appState.updateHistory && appState.updateHistory.length > 0 ? (
                appState.updateHistory.map(log => (
                  <div key={log.id} className="flex items-start gap-3 p-3 bg-gray-50 dark:bg-slate-800/50 rounded-2xl border border-gray-100 dark:border-slate-800">
                    <div className="mt-0.5">
                      {log.status === 'success' ? <CheckCircle2 className="w-4 h-4 text-emerald-500" /> : <AlertCircle className="w-4 h-4 text-red-500" />}
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-[10px] font-black uppercase text-gray-800 dark:text-white truncate">{log.fileName}</p>
                      <p className="text-[9px] text-gray-400 font-bold uppercase">{new Date(log.timestamp).toLocaleString()}</p>
                      {log.status === 'success' ? (
                        <p className="text-[9px] text-emerald-600 font-black mt-1 uppercase">{log.recordCount} itens processados</p>
                      ) : (
                        <p className="text-[9px] text-red-600 font-black mt-1 uppercase">Falha na importação</p>
                      )}
                    </div>
                  </div>
                ))
              ) : (
                <p className="text-[10px] text-center text-gray-400 font-bold uppercase py-6">Sem registros recentes.</p>
              )}
            </div>
          </div>

          <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h3 className="text-sm font-black mb-4 flex items-center gap-2 dark:text-white uppercase tracking-wider">
              <ClipboardList className="w-4 h-4 text-blue-600" /> Colar Dados
            </h3>
            <div className="space-y-3">
              <textarea placeholder="Cole o conteúdo do CSV aqui..." className="w-full px-4 py-3 rounded-xl border border-gray-100 dark:border-slate-800 bg-gray-50 dark:bg-slate-800 dark:text-white text-[11px] outline-none transition-all focus:ring-2 focus:ring-blue-500/20 h-24 resize-none font-mono" value={pasteContent} onChange={(e) => setPasteContent(e.target.value)} />
              <button onClick={() => processData(pasteContent, 'Colagem Manual')} disabled={!pasteContent.trim()} className="w-full bg-blue-600 disabled:opacity-50 text-white font-black py-3 rounded-xl text-[9px] uppercase flex items-center justify-center gap-2 shadow-lg hover:brightness-110 active:scale-95 transition-all"><Send className="w-3 h-3" /> Processar Dados Colados</button>
            </div>
          </div>

          <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h3 className="text-sm font-black mb-4 flex items-center gap-2 dark:text-white uppercase tracking-wider">
              <Upload className="w-4 h-4 text-purple-600" /> Upload de Arquivo
            </h3>
            <label className="border-2 border-dashed rounded-2xl p-6 flex flex-col items-center justify-center cursor-pointer border-purple-100 dark:border-slate-800 hover:border-purple-500 hover:bg-purple-50 dark:hover:bg-purple-900/10 transition-all group">
              <ArrowDownToLine className="w-6 h-6 text-purple-300 group-hover:text-purple-500 mb-2 transition-transform group-hover:translate-y-1" />
              <p className="text-[9px] text-purple-600 font-black uppercase">Importar .CSV Local</p>
              <input type="file" className="hidden" accept=".csv" onChange={handleFileUpload} />
            </label>
            {uploadStatus && (
              <div className={`mt-4 p-3 rounded-xl text-[10px] font-bold animate-in slide-in-from-top-2 ${uploadStatus.type === 'success' ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400' : uploadStatus.type === 'error' ? 'bg-red-50 text-red-700 dark:bg-red-900/20 dark:text-red-400' : 'bg-blue-50 text-blue-700 dark:bg-blue-900/20 dark:text-blue-400'}`}>{uploadStatus.message}</div>
            )}
          </div>
        </div>

        <div className="lg:col-span-2 space-y-8">
          <div className="bg-white dark:bg-slate-900 rounded-3xl shadow-xl border border-gray-100 dark:border-slate-800 overflow-hidden">
            <div className="p-6 border-b border-gray-50 dark:border-slate-800 flex justify-between items-center bg-gray-50/30 dark:bg-slate-800/20">
              <h3 className="text-sm font-black dark:text-white uppercase tracking-wider flex items-center gap-2">
                <FileText className="w-4 h-4 text-purple-500" /> Solicitações da Equipe
              </h3>
              {appState.requests.length > 0 && (
                <button onClick={onClearRequests} className="text-[9px] font-black text-red-500 uppercase hover:underline flex items-center gap-1 transition-all hover:scale-105 active:scale-95">
                  <Trash2 className="w-3 h-3" /> Limpar Histórico
                </button>
              )}
            </div>
            <div className="overflow-x-auto custom-scrollbar">
              {appState.requests.length === 0 ? (
                <div className="py-24 text-center opacity-30 flex flex-col items-center">
                  <Clock className="w-12 h-12 mb-4" />
                  <p className="text-[10px] font-black uppercase tracking-widest">Aguardando solicitações...</p>
                </div>
              ) : (
                <table className="w-full text-left border-collapse min-w-[600px]">
                  <thead className="bg-gray-50/50 dark:bg-slate-800/50">
                    <tr>
                      <th className="px-6 py-4 text-[9px] font-black text-gray-400 uppercase">Solicitante</th>
                      <th className="px-6 py-4 text-[9px] font-black text-gray-400 uppercase">Produto / Obs</th>
                      <th className="px-6 py-4 text-[9px] font-black text-gray-400 uppercase text-center">Ações</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-50 dark:divide-slate-800">
                    {appState.requests.map(req => (
                      <tr key={req.id} className="hover:bg-gray-50 dark:hover:bg-slate-800/40 transition-colors group">
                        <td className="px-6 py-4">
                          <p className="text-xs font-black dark:text-white uppercase">{req.solicitante}</p>
                          <p className="text-[8px] text-gray-400 font-bold">{new Date(req.dataSolicitacao).toLocaleString()}</p>
                        </td>
                        <td className="px-6 py-4">
                          <div className="flex items-center gap-2 mb-1">
                            <p className="text-xs font-bold dark:text-slate-300 line-clamp-1">{req.productName}</p>
                            {req.isValidadeCurta && (
                              <span className="text-[7px] bg-orange-100 text-orange-600 dark:bg-orange-900/30 dark:text-orange-400 px-1 py-0.5 rounded font-black uppercase flex items-center gap-0.5"><Timer className="w-2 h-2" /> Validade Curta</span>
                            )}
                          </div>
                          <div className="flex gap-2 items-center flex-wrap">
                            <span className="text-[8px] bg-blue-50 dark:bg-blue-900/30 text-blue-500 px-1.5 py-0.5 rounded font-black uppercase">{req.tipo}</span>
                            <span className="text-[8px] text-gray-500 font-bold">{req.quantidade} {req.unidade}</span>
                          </div>
                        </td>
                        <td className="px-6 py-4 text-center">
                          <div className="flex flex-col items-center gap-2">
                             <span className={`text-[7px] font-black uppercase px-2 py-0.5 rounded-full ${
                              req.status === 'Pendente' ? 'bg-amber-100 text-amber-700 dark:bg-amber-900/20 dark:text-amber-400' : 
                              req.status === 'Aprovado' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400' : 
                              'bg-red-100 text-red-700 dark:bg-red-900/20 dark:text-red-400'
                            }`}>{req.status}</span>
                            {req.status === 'Pendente' && (
                              <div className="flex justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button onClick={() => onUpdateRequestStatus(req.id, 'Aprovado')} className="p-2 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 rounded-lg hover:bg-emerald-600 hover:text-white transition-all" title="Aprovar"><Check className="w-3 h-3" /></button>
                                <button onClick={() => onUpdateRequestStatus(req.id, 'Recusado')} className="p-2 bg-red-50 dark:bg-red-900/20 text-red-600 rounded-lg hover:bg-red-600 hover:text-white transition-all" title="Recusar"><X className="w-3 h-3" /></button>
                              </div>
                            )}
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { UserPortal } from './components/UserPortal';
import { AdminPortal } from './components/AdminPortal';
import { AppState, Product, StockRequest, WhatsAppConfig, UpdateLog } from './types';
import { LayoutDashboard, ShieldCheck, Sun, Moon, KeyRound, LogOut, ChevronRight, Store, X, Loader2 } from 'lucide-react';
import Papa from 'papaparse';

const THEME_KEY = 'marsil_theme_pref';
const AUTH_KEY = 'marsil_auth_role';
const PRODUCTS_KEY = 'marsil_local_products';
const VENDEDORES_KEY = 'marsil_vendedores_list';
const REQUESTS_KEY = 'marsil_requests_history';
const SYNC_URL_KEY = 'marsil_sync_url';
const UPDATE_HISTORY_KEY = 'marsil_update_history';

const PASSWORDS = {
  VENDOR: '@marsil2026',
  ADMIN: '@adminMarsil2026'
};

const DEFAULT_VENDEDORES = [
  "ADALTON LUIZ", "AIRTON DONIZETTI", "ANA CAMARGO", "ANA PAULA", "CARLOS ROSEIRO",
  "DOUGLAS PITELLI", "EDMILSON LEAL", "FERNANDO APARECIDO", "GUSTAVO PAULINO",
  "JOAO JOSE", "JOAO MANUEL", "LEONARDO APARECIDO", "LUIS ALEXANDRE",
  "MARCELO SANTOS", "MARCO AURELIO", "NIVALDO NEVES", "ROSIMAR FREITAS",
  "ROZIMARA SOUZA", "TELMA CRISTINA", "WASHINGTON BELMIRO", "OUTRO"
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'user' | 'admin'>('user');
  const [authRole, setAuthRole] = useState<'none' | 'vendor' | 'admin'>(() => {
    return (localStorage.getItem(AUTH_KEY) as any) || 'none';
  });

  const [loginTarget, setLoginTarget] = useState<'vendedor' | 'admin' | null>(null);
  const [passwordInput, setPasswordInput] = useState('');
  const [loginError, setLoginError] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);

  const [isDarkMode, setIsDarkMode] = useState(() => {
    const savedTheme = localStorage.getItem(THEME_KEY);
    return savedTheme === 'dark';
  });

  const [appState, setAppState] = useState<AppState>(() => {
    const savedProducts = localStorage.getItem(PRODUCTS_KEY);
    const savedVendedores = localStorage.getItem(VENDEDORES_KEY);
    const savedRequests = localStorage.getItem(REQUESTS_KEY);
    const savedHistory = localStorage.getItem(UPDATE_HISTORY_KEY);

    let finalVendedores = DEFAULT_VENDEDORES;
    if (savedVendedores) {
      try {
        const parsed = JSON.parse(savedVendedores);
        if (Array.isArray(parsed) && parsed.length > 0) finalVendedores = parsed;
      } catch (e) { finalVendedores = DEFAULT_VENDEDORES; }
    }

    return { 
      products: savedProducts ? JSON.parse(savedProducts) : [], 
      requests: savedRequests ? JSON.parse(savedRequests) : [], 
      vendedores: finalVendedores,
      whatsappConfig: { enabled: true, phoneNumber: '5511999999999' },
      updateHistory: savedHistory ? JSON.parse(savedHistory) : []
    };
  });

  const mapCSVData = (data: any[]) => {
    return data.map((row: any, i: number) => {
      const findVal = (keys: string[]) => {
        const key = Object.keys(row).find(k => 
          keys.some(s => k.trim().toLowerCase() === s.toLowerCase()) ||
          keys.some(s => k.trim().toLowerCase().includes(s.toLowerCase()))
        );
        return key ? String(row[key]).trim() : '';
      };

      return {
        id: `p-${i}-${Date.now()}`,
        fornecedor: findVal(['Fornecedor', 'Forn', 'Marca', 'Fabricante']),
        codigo: findVal(['Código', 'Cód', 'Ref', 'Cod Item', 'Item', 'codigo', 'ID', 'Referência']),
        situacao: findVal(['Situação', 'Status', 'Sit', 'Disponibilidade']),
        comprador: findVal(['Comprador', 'Responsável', 'Buyer']),
        produto: findVal(['Produto', 'Descrição', 'Nome', 'Desc', 'produto']),
        sabor: findVal(['Sabor', 'Gosto', 'Flavor', 'Variante']),
        embalagem: findVal(['Embalagem', 'Emb', 'Pack']),
        estoqueMarsil: parseInt(findVal(['Marsil', 'SP', 'Estoque Marsil', 'Matriz'])) || 0,
        estoqueBoraceia: parseInt(findVal(['Boraceia', 'Boracéia', 'Filial', 'Estoque Boraceia'])) || 0,
      };
    }).filter(p => p.produto && p.produto !== '');
  };

  const syncData = useCallback(async (url: string) => {
    setIsSyncing(true);
    return new Promise<void>((resolve, reject) => {
      Papa.parse(url, {
        download: true,
        header: true,
        skipEmptyLines: true,
        complete: (results) => {
          const mapped = mapCSVData(results.data);
          if (mapped.length > 0) {
            setAppState(prev => ({ 
              ...prev, 
              products: mapped,
              updateHistory: [{
                id: Date.now().toString(),
                timestamp: new Date().toISOString(),
                fileName: 'Sincronização Automática',
                recordCount: mapped.length,
                status: 'success'
              }, ...prev.updateHistory].slice(0, 20)
            }));
          }
          setIsSyncing(false);
          resolve();
        },
        error: (error) => {
          console.error("Erro na sincronização:", error);
          setIsSyncing(false);
          reject(error);
        }
      });
    });
  }, []);

  const handleManualRefresh = async () => {
    const url = localStorage.getItem(SYNC_URL_KEY);
    if (url) {
      await syncData(url);
    } else {
      alert("Nenhum link de sincronização configurado pelo administrador.");
    }
  };

  useEffect(() => {
    const initApp = async () => {
      const params = new URLSearchParams(window.location.search);
      const urlSync = params.get('s');
      const urlVendors = params.get('v');
      const storedSyncUrl = localStorage.getItem(SYNC_URL_KEY);

      let initialVendedores = appState.vendedores;

      if (urlVendors) {
        try {
          const parsed = JSON.parse(decodeURIComponent(urlVendors));
          if (Array.isArray(parsed) && parsed.length > 0) {
            initialVendedores = parsed;
            localStorage.setItem(VENDEDORES_KEY, JSON.stringify(parsed));
          }
        } catch (e) { console.error(e); }
      }

      const finalSyncUrl = urlSync || storedSyncUrl;

      if (finalSyncUrl) {
        if (urlSync) localStorage.setItem(SYNC_URL_KEY, urlSync);
        try {
          await syncData(finalSyncUrl);
        } catch (e) {
          console.error("Falha ao sincronizar dados iniciais.");
        } finally {
          setIsLoading(false);
        }
      } else {
        if (urlVendors) setAppState(prev => ({ ...prev, vendedores: initialVendedores }));
        setTimeout(() => setIsLoading(false), 800);
      }
    };
    initApp();
  }, []);

  useEffect(() => { localStorage.setItem(AUTH_KEY, authRole); }, [authRole]);
  useEffect(() => {
    localStorage.setItem(PRODUCTS_KEY, JSON.stringify(appState.products));
    localStorage.setItem(VENDEDORES_KEY, JSON.stringify(appState.vendedores));
    localStorage.setItem(REQUESTS_KEY, JSON.stringify(appState.requests));
    localStorage.setItem(UPDATE_HISTORY_KEY, JSON.stringify(appState.updateHistory));
  }, [appState]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem(THEME_KEY, 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem(THEME_KEY, 'light');
    }
  }, [isDarkMode]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const requiredPass = loginTarget === 'admin' ? PASSWORDS.ADMIN : PASSWORDS.VENDOR;
    if (passwordInput === requiredPass) {
      const role = loginTarget === 'admin' ? 'admin' : 'vendor';
      setAuthRole(role);
      setActiveTab(loginTarget === 'admin' ? 'admin' : 'user');
      setLoginError(false);
      setLoginTarget(null);
    } else {
      setLoginError(true);
      setTimeout(() => setLoginError(false), 3000);
    }
    setPasswordInput('');
  };

  const handleLogout = () => {
    setAuthRole('none');
    setLoginTarget(null);
    setPasswordInput('');
    setActiveTab('user');
    localStorage.removeItem(AUTH_KEY);
  };

  const handleUploadData = (newProducts: Product[]) => {
    setAppState(prev => ({ ...prev, products: newProducts }));
  };

  const handleRegisterUpdate = (log: UpdateLog) => {
    setAppState(prev => ({
      ...prev,
      updateHistory: [log, ...prev.updateHistory].slice(0, 20)
    }));
  };

  const handleAddVendedor = (name: string) => {
    if (!appState.vendedores.includes(name)) {
      setAppState(prev => ({ ...prev, vendedores: [...prev.vendedores, name].sort() }));
    }
  };

  const handleRemoveVendedor = (name: string) => {
    setAppState(prev => ({ ...prev, vendedores: prev.vendedores.filter(v => v !== name) }));
  };

  const handleUpdateWhatsApp = (config: WhatsAppConfig) => {
    setAppState(prev => ({ ...prev, whatsappConfig: config }));
  };

  const handleSubmitRequest = (request: StockRequest) => {
    setAppState(prev => ({ ...prev, requests: [request, ...prev.requests] }));
  };

  const handleUpdateRequest = (updatedRequest: StockRequest) => {
    setAppState(prev => ({
      ...prev,
      requests: prev.requests.map(r => String(r.id) === String(updatedRequest.id) ? updatedRequest : r)
    }));
  };

  const handleDeleteRequest = useCallback((requestId: string) => {
    setAppState(prev => ({ ...prev, requests: prev.requests.filter(r => String(r.id) !== String(requestId)) }));
  }, []);

  const handleClearUserRequests = useCallback((solicitante: string) => {
    setAppState(prev => ({ ...prev, requests: prev.requests.filter(r => r.solicitante !== solicitante) }));
  }, []);

  const handleUpdateRequestStatus = (requestId: string, status: StockRequest['status']) => {
    setAppState(prev => ({
      ...prev,
      requests: prev.requests.map(r => String(r.id) === String(requestId) ? { ...r, status } : r)
    }));
  };

  const handleClearRequests = () => {
    if (window.confirm('Limpar histórico local de pedidos?')) {
      setAppState(prev => ({ ...prev, requests: [] }));
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-slate-950">
        <div className="flex flex-col items-center gap-4">
          <Loader2 className="w-8 h-8 text-blue-600 animate-spin" />
          <p className="text-[10px] font-black uppercase tracking-widest text-gray-400">Sincronizando Dados...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-slate-950 text-gray-900 dark:text-slate-100 transition-colors duration-300">
      <header className="bg-white dark:bg-slate-900 border-b border-gray-200 dark:border-slate-800 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <div className="bg-blue-600 p-2 rounded-xl shrink-0">
                <LayoutDashboard className="w-5 h-5 text-white" />
              </div>
              <div className="flex flex-col">
                <h1 className="text-lg font-black tracking-tight dark:text-white">Marsil & Boracéia</h1>
                <p className="text-[9px] text-gray-400 font-bold uppercase tracking-tighter">Gestão de Estoque</p>
              </div>
            </div>
            <div className="flex items-center gap-4">
              <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-gray-400 hover:text-blue-500 transition-colors">
                {isDarkMode ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
              </button>
              {authRole !== 'none' && (
                <div className="flex items-center gap-2">
                  <div className="bg-gray-100 dark:bg-slate-800 p-1 rounded-xl flex">
                    <button onClick={() => setActiveTab('user')} className={`px-3 py-1.5 text-[10px] font-black rounded-lg uppercase ${activeTab === 'user' ? 'bg-white dark:bg-slate-700 text-blue-600 shadow-sm' : 'text-gray-400'}`}>Consulta</button>
                    {authRole === 'admin' && (
                      <button onClick={() => setActiveTab('admin')} className={`px-3 py-1.5 text-[10px] font-black rounded-lg uppercase ${activeTab === 'admin' ? 'bg-white dark:bg-slate-700 text-blue-600 shadow-sm' : 'text-gray-400'}`}>Admin</button>
                    )}
                  </div>
                  <button onClick={handleLogout} className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-xl transition-colors"><LogOut className="w-4 h-4" /></button>
                </div>
              )}
            </div>
          </div>
        </div>
      </header>
      <main className="flex-grow p-4 sm:p-8 flex flex-col items-center">
        {authRole === 'none' ? (
          !loginTarget ? (
            <div className="w-full max-w-2xl mt-12 animate-in fade-in zoom-in-95 duration-500 space-y-8">
              <div className="text-center space-y-2">
                <h2 className="text-4xl font-black dark:text-white tracking-tight">Painel de Estoque</h2>
                <p className="text-gray-500 dark:text-slate-400 text-sm">Acesse para consultar itens e realizar pedidos.</p>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <button onClick={() => setLoginTarget('vendedor')} className="group bg-white dark:bg-slate-900 p-8 rounded-3xl shadow-xl hover:shadow-2xl border-2 border-transparent hover:border-emerald-500 transition-all flex flex-col items-center space-y-4">
                  <div className="w-16 h-16 bg-emerald-50 dark:bg-emerald-900/30 rounded-2xl flex items-center justify-center group-hover:bg-emerald-600 group-hover:text-white transition-all">
                    <Store className="w-8 h-8 text-emerald-600 group-hover:text-white" />
                  </div>
                  <h3 className="text-xl font-bold dark:text-white">Vendedor</h3>
                  <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Acessar <ChevronRight className="w-4 h-4 inline" /></p>
                </button>
                <button onClick={() => setLoginTarget('admin')} className="group bg-white dark:bg-slate-900 p-8 rounded-3xl shadow-xl hover:shadow-2xl border-2 border-transparent hover:border-blue-500 transition-all flex flex-col items-center space-y-4">
                  <div className="w-16 h-16 bg-blue-50 dark:bg-blue-900/30 rounded-2xl flex items-center justify-center group-hover:bg-blue-600 group-hover:text-white transition-all">
                    <ShieldCheck className="w-8 h-8 text-blue-600 group-hover:text-white" />
                  </div>
                  <h3 className="text-xl font-bold dark:text-white">Administrador</h3>
                  <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Configurar <ChevronRight className="w-4 h-4 inline" /></p>
                </button>
              </div>
            </div>
          ) : (
            <div className="w-full max-w-sm mt-12 animate-in slide-in-from-bottom-8 duration-500 px-4">
              <div className="bg-white dark:bg-slate-900 p-8 rounded-3xl shadow-2xl border border-gray-100 dark:border-slate-800 text-center relative">
                <button onClick={() => setLoginTarget(null)} className="absolute left-4 top-4 p-2 text-gray-400 hover:text-gray-600 transition-colors"><X className="w-4 h-4" /></button>
                <div className={`w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-6 ${loginTarget === 'admin' ? 'bg-blue-50 dark:bg-blue-900/30' : 'bg-emerald-50 dark:bg-emerald-900/30'}`}>
                  {loginTarget === 'admin' ? <ShieldCheck className="w-8 h-8 text-blue-600" /> : <Store className="w-8 h-8 text-emerald-600" />}
                </div>
                <h2 className="text-2xl font-black dark:text-white mb-6">Login {loginTarget === 'admin' ? 'Admin' : 'Vendedor'}</h2>
                <form onSubmit={handleLogin} className="space-y-4">
                  <div className="relative">
                    <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                    <input autoFocus type="password" placeholder="Sua senha..." value={passwordInput} onChange={(e) => setPasswordInput(e.target.value)} className="w-full pl-12 pr-4 py-4 rounded-2xl border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 outline-none transition-all dark:text-white font-bold" />
                  </div>
                  {loginError && <p className="text-[10px] text-red-500 font-bold uppercase">Senha incorreta!</p>}
                  <button type="submit" className="w-full bg-blue-600 text-white font-black py-4 rounded-2xl shadow-lg active:scale-95 transition-all uppercase tracking-widest text-xs">Entrar</button>
                </form>
              </div>
            </div>
          )
        ) : (
          activeTab === 'user' ? (
            <UserPortal 
              products={appState.products} 
              requests={appState.requests} 
              vendedores={appState.vendedores} 
              whatsappConfig={appState.whatsappConfig} 
              onSubmitRequest={handleSubmitRequest}
              onDeleteRequest={handleDeleteRequest}
              onClearUserRequests={handleClearUserRequests}
              onUpdateRequest={handleUpdateRequest}
              isSyncing={isSyncing}
              onManualRefresh={handleManualRefresh}
              lastUpdate={appState.updateHistory[0]?.timestamp}
            />
          ) : (
            <AdminPortal 
              appState={appState} 
              onUploadData={handleUploadData} 
              onRegisterUpdate={handleRegisterUpdate}
              onAddVendedor={handleAddVendedor} 
              onRemoveVendedor={handleRemoveVendedor} 
              onUpdateWhatsApp={handleUpdateWhatsApp} 
              onUpdateRequestStatus={handleUpdateRequestStatus} 
              onClearRequests={handleClearRequests} 
            />
          )
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useCallback } from 'react';
import { Search, ShoppingCart, Calendar, RefreshCw, AlertTriangle, Building2, Store, ListPlus, X, Send, User, Hash, FileText, Filter, Copy, Check, Clock, History, Clipboard, ArrowRight, PlusCircle, CheckCircle2, Candy, Trash2, Edit3, MessageSquareText, Timer, Info } from 'lucide-react';
import { Product, StockRequest, WhatsAppConfig, RequestType, UnitType } from '../types';

interface UserPortalProps {
  products: Product[];
  requests: StockRequest[];
  vendedores: string[];
  whatsappConfig: WhatsAppConfig;
  onSubmitRequest: (req: StockRequest) => void;
  onDeleteRequest: (id: string) => void;
  onClearUserRequests: (solicitante: string) => void;
  onUpdateRequest: (req: StockRequest) => void;
  isSyncing?: boolean;
  onManualRefresh?: () => void;
  lastUpdate?: string;
}

const UNIT_OPTIONS: UnitType[] = ['UN', 'CX', 'DP', 'PCT', 'PT', 'SC', 'FD'];

export const UserPortal: React.FC<UserPortalProps> = ({ 
  products, 
  requests, 
  vendedores, 
  whatsappConfig, 
  onSubmitRequest,
  onDeleteRequest,
  onClearUserRequests,
  onUpdateRequest,
  isSyncing = false,
  onManualRefresh,
  lastUpdate
}) => {
  const [activeView, setActiveView] = useState<'consulta' | 'historico'>('consulta');
  const [filterCodigo, setFilterCodigo] = useState('');
  const [filterDescricao, setFilterDescricao] = useState('');
  const [filterFornecedor, setFilterFornecedor] = useState('');

  const [selected, setSelected] = useState<Product | null>(null);
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);
  const [copySuccess, setCopySuccess] = useState<string | null>(null);
  const [requestStatus, setRequestStatus] = useState<'idle' | 'success'>('idle');

  // Request Form States
  const [quant, setQuant] = useState<number>(1);
  const [unit, setUnit] = useState<UnitType>('CX');
  const [type, setType] = useState<RequestType>('Aposta na Venda');
  const [solicitante, setSolicitante] = useState(() => {
    return '';
  });
  const [observacoes, setObservacoes] = useState('');
  const [isValidadeCurta, setIsValidadeCurta] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Filtro Combinado
  const filteredProducts = useMemo(() => {
    const cod = filterCodigo.toLowerCase().trim();
    const desc = filterDescricao.toLowerCase().trim();
    const forn = filterFornecedor.toLowerCase().trim();

    if (!cod && !desc && !forn) return [];

    return products.filter(p => {
      const matchCod = !cod || String(p.codigo).toLowerCase().includes(cod);
      const matchDesc = !desc || p.produto.toLowerCase().includes(desc);
      const matchForn = !forn || p.fornecedor.toLowerCase().includes(forn);
      return matchCod && matchDesc && matchForn;
    }).slice(0, 40);
  }, [products, filterCodigo, filterDescricao, filterFornecedor]);

  // Histórico filtrado pelo solicitante atual
  const myRequests = useMemo(() => {
    if (!solicitante) return [];
    return requests.filter(r => r.solicitante === solicitante);
  }, [requests, solicitante]);

  const handleCopy = (text: string, id: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopySuccess(id);
      setTimeout(() => setCopySuccess(null), 2000);
    });
  };

  const handleCopyFormattedList = () => {
    const dateStr = new Date().toLocaleDateString('pt-BR');
    const itemsStr = myRequests.map(r => 
      `QTD: ${r.quantidade} UNIDADE: ${r.unidade} - Cód: ${r.productCode}${r.productSabor ? ` (${r.productSabor})` : ''}${r.isValidadeCurta ? ' [VALIDADE CURTA]' : ''}${r.observacoes ? ` [Obs: ${r.observacoes}]` : ''}`
    ).join('\n');

    const fullText = `📦 PEDIDO MARSIL
📅 Data do Pedido: ${dateStr}
👤 Vendedor: ${solicitante || 'Não Identificado'}

${itemsStr}

Pedido Extra Boracéia`;

    handleCopy(fullText, 'hist-all');
  };

  const handleClearCart = () => {
    if (window.confirm('Deseja realmente excluir TODOS os itens do seu pedido atual?')) {
      onClearUserRequests(solicitante);
    }
  };

  const handleEditRequest = (req: StockRequest) => {
    const product = products.find(p => String(p.id) === String(req.productId) || String(p.codigo) === String(req.productCode));
    if (product) {
      setSelected(product);
      setEditingRequestId(req.id);
      setQuant(req.quantidade);
      setUnit(req.unidade);
      setType(req.tipo);
      setSolicitante(req.solicitante);
      setObservacoes(req.observacoes || '');
      setIsValidadeCurta(req.isValidadeCurta || false);
    }
  };

  const handleSendRequest = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selected || !solicitante) return;
    setIsSubmitting(true);

    if (editingRequestId) {
      const originalReq = requests.find(r => String(r.id) === String(editingRequestId));
      if (originalReq) {
        const updatedReq: StockRequest = {
          ...originalReq,
          quantidade: quant,
          unidade: unit,
          tipo: type,
          solicitante: solicitante,
          observacoes: observacoes,
          isValidadeCurta: isValidadeCurta,
          productSabor: selected.sabor || ''
        };
        onUpdateRequest(updatedReq);
      }
    } else {
      const newReq: StockRequest = {
        id: `req-${Date.now()}`,
        productId: selected.id,
        productName: selected.produto,
        productCode: String(selected.codigo),
        productSabor: selected.sabor || '',
        quantidade: quant,
        unidade: unit,
        tipo: type,
        solicitante: solicitante,
        observacoes: observacoes,
        isValidadeCurta: isValidadeCurta,
        dataSolicitacao: new Date().toISOString(),
        status: 'Pendente'
      };
      onSubmitRequest(newReq);
    }

    setRequestStatus('success');

    setTimeout(() => {
      setIsSubmitting(false);
      setSelected(null);
      setEditingRequestId(null);
      setRequestStatus('idle');
      setQuant(1);
      setObservacoes('');
      setIsValidadeCurta(false);
    }, 1200);
  };

  const getStatusColor = (status: string) => {
    const s = status.toLowerCase();
    if (s.includes('disponível') || s.includes('ativo') || s.includes('estoque')) return 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400';
    if (s.includes('falta') || s.includes('esgotado') || s.includes('inativo')) return 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400';
    if (s.includes('chegando') || s.includes('pedido') || s.includes('trânsito')) return 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400';
    return 'bg-gray-100 text-gray-700 dark:bg-slate-800 dark:text-gray-400';
  };

  const hasFilters = filterCodigo || filterDescricao || filterFornecedor;

  const lastUpdateStr = lastUpdate ? new Date(lastUpdate).toLocaleString('pt-BR', { hour: '2-digit', minute: '2-digit', second: '2-digit' }) : 'N/A';

  return (
    <div className="max-w-4xl w-full mx-auto space-y-6 animate-in fade-in duration-500">
      <div className={`p-6 rounded-3xl transition-all duration-500 border ${!solicitante ? 'bg-blue-600 border-blue-500 shadow-2xl shadow-blue-500/20 text-white' : 'bg-white dark:bg-slate-900 border-gray-100 dark:border-slate-800 shadow-sm'}`}>
        <div className="flex flex-col sm:flex-row items-center gap-6">
          <div className="flex-grow space-y-2">
            <h3 className={`text-base font-black uppercase tracking-widest flex items-center gap-2 ${!solicitante ? 'text-white' : 'dark:text-white'}`}>
              <User className={`w-5 h-5 ${!solicitante ? 'text-blue-100' : 'text-blue-500'}`} /> 
              Vendedor Responsável
            </h3>
            <p className={`text-[10px] font-bold uppercase ${!solicitante ? 'text-blue-100' : 'text-gray-400'}`}>
              {!solicitante ? 'Selecione sua identificação para começar a consulta' : 'Operando como ' + solicitante}
            </p>
          </div>

          <div className="relative group w-full sm:w-80">
            <select 
              className={`w-full pl-5 pr-10 py-4 rounded-2xl outline-none text-[11px] font-black uppercase tracking-wider shadow-sm transition-all appearance-none cursor-pointer border-2 ${!solicitante ? 'bg-white text-blue-600 border-white' : 'bg-gray-50 dark:bg-slate-800 dark:text-white border-transparent focus:border-blue-500'}`}
              value={solicitante}
              onChange={(e) => setSolicitante(e.target.value)}
            >
              <option value="" disabled>Selecione um Vendedor...</option>
              {vendedores.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
            <div className={`absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none ${!solicitante ? 'text-blue-600' : 'text-gray-400'}`}>
              <ArrowRight className="w-3 h-3 rotate-90" />
            </div>
          </div>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
        <div className="flex bg-white dark:bg-slate-900 p-1.5 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800 w-fit">
          <button 
            onClick={() => setActiveView('consulta')}
            className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeView === 'consulta' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-gray-400 hover:text-blue-500'}`}
          >
            <Search className="w-3.5 h-3.5" /> Consulta
          </button>
          <button 
            onClick={() => setActiveView('historico')}
            className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeView === 'historico' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-gray-400 hover:text-blue-500'}`}
          >
            <History className="w-3.5 h-3.5" /> Carrinho ({myRequests.length})
          </button>
        </div>

        <div className="flex items-center gap-3">
          <div className="hidden xs:flex flex-col items-end">
            <p className="text-[8px] font-black text-gray-400 uppercase leading-none">Última Sincronização</p>
            <p className="text-[10px] font-bold text-blue-500 leading-tight">{lastUpdateStr}</p>
          </div>
          <button 
            onClick={onManualRefresh}
            disabled={isSyncing}
            className={`flex items-center gap-2 px-5 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all border shadow-sm ${isSyncing ? 'bg-gray-100 border-gray-100 text-gray-400 cursor-not-allowed' : 'bg-white dark:bg-slate-900 border-gray-100 dark:border-slate-800 text-blue-600 hover:bg-blue-50'}`}
          >
            <RefreshCw className={`w-3.5 h-3.5 ${isSyncing ? 'animate-spin' : ''}`} />
            {isSyncing ? 'Sincronizando...' : 'Atualizar Dados'}
          </button>
        </div>
      </div>

      {activeView === 'consulta' ? (
        <div className={`space-y-6 transition-opacity duration-300 ${!solicitante ? 'opacity-40 pointer-events-none grayscale' : 'opacity-100'}`}>
          <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-xl border border-gray-100 dark:border-slate-800">
            <div className="flex justify-between items-end mb-6">
              <div>
                <h2 className="text-base font-black flex items-center gap-2 uppercase tracking-widest dark:text-white mb-1">
                  <Filter className="w-5 h-5 text-blue-600" /> Pesquisa Avançada
                </h2>
                <p className="text-[10px] text-gray-400 font-bold uppercase">Busca por Código, Descrição ou Fabricante</p>
              </div>
              {hasFilters && (
                <button onClick={() => { setFilterCodigo(''); setFilterDescricao(''); setFilterFornecedor(''); }} className="text-[10px] font-black text-red-500 uppercase hover:underline flex items-center gap-1 pb-1">
                  <X className="w-3 h-3" /> Limpar Filtros
                </button>
              )}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <div className="relative group">
                <Hash className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-300 group-focus-within:text-blue-500 transition-colors" />
                <input type="text" placeholder="Código Item" className="w-full pl-11 pr-4 py-4 rounded-2xl border border-gray-100 dark:border-slate-800 bg-gray-50 dark:bg-slate-800 outline-none text-xs font-bold dark:text-white focus:ring-2 focus:ring-blue-500/20 transition-all" value={filterCodigo} onChange={(e) => setFilterCodigo(e.target.value)} />
              </div>
              <div className="relative group">
                <FileText className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-300 group-focus-within:text-blue-500 transition-colors" />
                <input type="text" placeholder="Nome / Descrição" className="w-full pl-11 pr-4 py-4 rounded-2xl border border-gray-100 dark:border-slate-800 bg-gray-50 dark:bg-slate-800 outline-none text-xs font-bold dark:text-white focus:ring-2 focus:ring-blue-500/20 transition-all" value={filterDescricao} onChange={(e) => setFilterDescricao(e.target.value)} />
              </div>
              <div className="relative group">
                <Building2 className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-300 group-focus-within:text-blue-500 transition-colors" />
                <input type="text" placeholder="Fornecedor" className="w-full pl-11 pr-4 py-4 rounded-2xl border border-gray-100 dark:border-slate-800 bg-gray-50 dark:bg-slate-800 outline-none text-xs font-bold dark:text-white focus:ring-2 focus:ring-blue-500/20 transition-all" value={filterFornecedor} onChange={(e) => setFilterFornecedor(e.target.value)} />
              </div>
            </div>

            <div className="mt-8 space-y-3 max-h-[500px] overflow-y-auto custom-scrollbar pr-1">
              {filteredProducts.map(p => (
                <div key={p.id} className={`group w-full p-5 rounded-3xl border flex flex-col sm:flex-row sm:items-center justify-between gap-4 transition-all ${selected?.id === p.id ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20 ring-2 ring-blue-500/20' : 'border-gray-50 dark:border-slate-800 hover:bg-gray-50 dark:hover:bg-slate-800/60'}`}>
                  <div className="text-left flex-grow">
                    <div className="flex items-center gap-2 mb-2">
                      <div className="flex items-center bg-blue-600 text-white px-2 py-0.5 rounded-full">
                        <span className="text-[9px] font-black flex items-center gap-1 mr-2"><Hash className="w-2.5 h-2.5" /> {p.codigo}</span>
                        <button onClick={(e) => { e.stopPropagation(); handleCopy(p.codigo, `p-cod-${p.id}`); }} className="hover:text-blue-200 transition-colors">
                          {copySuccess === `p-cod-${p.id}` ? <Check className="w-2.5 h-2.5" /> : <Copy className="w-2.5 h-2.5" />}
                        </button>
                      </div>
                      {p.situacao && (
                        <span className={`text-[9px] px-2 py-0.5 rounded-full font-black uppercase ${getStatusColor(p.situacao)}`}>
                          {p.situacao}
                        </span>
                      )}
                    </div>
                    <p className="text-sm font-black uppercase line-clamp-2 dark:text-white leading-tight mb-2 group-hover:text-blue-600 transition-colors">{p.produto}</p>
                    <div className="flex flex-wrap items-center gap-4">
                      <span className="text-[10px] text-gray-500 dark:text-gray-400 font-bold uppercase flex items-center gap-1">
                        <Building2 className="w-3 h-3 text-blue-500" /> {p.fornecedor}
                      </span>
                      {p.sabor && (
                        <span className="text-[10px] text-pink-500 dark:text-pink-400 font-bold uppercase flex items-center gap-1">
                          <Candy className="w-3 h-3" /> {p.sabor}
                        </span>
                      )}
                    </div>
                  </div>

                  <div className="flex justify-between sm:justify-end gap-6 border-t sm:border-t-0 pt-4 sm:pt-0 dark:border-slate-800 items-center">
                    <div className="flex gap-4 mr-2">
                      <div className="text-right">
                        <p className="text-base font-black dark:text-white leading-none">{p.estoqueMarsil}</p>
                        <p className="text-[8px] font-black uppercase text-gray-400 mt-1">Matriz</p>
                      </div>
                      <div className="text-right">
                        <p className="text-base font-black text-emerald-600 leading-none">{p.estoqueBoraceia}</p>
                        <p className="text-[8px] font-black uppercase text-gray-400 mt-1">Boracéia</p>
                      </div>
                    </div>
                    <button 
                      type="button"
                      disabled={!solicitante}
                      onClick={() => {
                        setEditingRequestId(null);
                        setSelected(p);
                        setQuant(1);
                        setUnit('CX');
                        setType('Aposta na Venda');
                        setObservacoes('');
                        setIsValidadeCurta(false);
                      }} 
                      className="flex items-center gap-2 px-6 py-3.5 bg-blue-600 hover:bg-blue-700 disabled:bg-gray-200 dark:disabled:bg-slate-800 text-white rounded-2xl shadow-xl shadow-blue-500/30 active:scale-95 transition-all text-[11px] font-black uppercase tracking-widest disabled:shadow-none"
                    >
                      <ShoppingCart className="w-4 h-4" /> Solicitar
                    </button>
                  </div>
                </div>
              ))}

              {!hasFilters && (
                <div className="text-center py-32 opacity-20 flex flex-col items-center">
                  <Search className="w-16 h-16 mb-4" />
                  <p className="text-xs font-black uppercase tracking-widest">Utilize os filtros acima para pesquisar o catálogo</p>
                </div>
              )}
            </div>
          </div>
        </div>
      ) : (
        <div className="bg-white dark:bg-slate-900 rounded-3xl shadow-xl border border-gray-100 dark:border-slate-800 overflow-hidden animate-in slide-in-from-right-4">
          <div className="p-6 border-b border-gray-50 dark:border-slate-800 flex flex-col sm:flex-row justify-between items-center bg-gray-50/20 dark:bg-slate-800/20 gap-4">
            <div>
              <h3 className="text-sm font-black dark:text-white uppercase tracking-wider flex items-center gap-2">
                <History className="w-4 h-4 text-blue-500" /> Carrinho de Pedidos
              </h3>
              <p className="text-[9px] text-gray-400 font-bold uppercase mt-1">Vendedor Ativo: {solicitante || '---'}</p>
            </div>
            <div className="flex gap-2">
              <button 
                onClick={handleClearCart}
                disabled={myRequests.length === 0}
                className="text-[9px] font-black bg-red-50 dark:bg-red-900/30 text-red-600 px-4 py-2.5 rounded-xl uppercase flex items-center gap-2 hover:brightness-95 transition-all shadow-sm disabled:opacity-30"
              >
                <Trash2 className="w-3.5 h-3.5" />
                Limpar
              </button>
              <button 
                onClick={handleCopyFormattedList}
                disabled={myRequests.length === 0}
                className="text-[9px] font-black bg-blue-50 dark:bg-blue-900/30 text-blue-600 px-4 py-2.5 rounded-xl uppercase flex items-center gap-2 hover:brightness-95 transition-all shadow-sm disabled:opacity-30"
              >
                {copySuccess === 'hist-all' ? <Check className="w-3.5 h-3.5" /> : <Clipboard className="w-3.5 h-3.5" />}
                Copiar Lista
              </button>
            </div>
          </div>
          <div className="overflow-x-auto">
            {myRequests.length === 0 ? (
              <div className="py-24 text-center opacity-30 flex flex-col items-center">
                <Clock className="w-12 h-12 mb-4" />
                <p className="text-[10px] font-black uppercase tracking-widest">Seu carrinho de solicitações está vazio.</p>
              </div>
            ) : (
              <table className="w-full text-left border-collapse min-w-[500px]">
                <thead className="bg-gray-50/50 dark:bg-slate-800/50">
                  <tr>
                    <th className="px-6 py-4 text-[9px] font-black text-gray-400 uppercase">Item</th>
                    <th className="px-6 py-4 text-[9px] font-black text-gray-400 uppercase">Solicitação</th>
                    <th className="px-6 py-4 text-[9px] font-black text-gray-400 uppercase text-center">Ações</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50 dark:divide-slate-800">
                  {myRequests.map(req => (
                    <tr key={req.id} className="hover:bg-gray-50 dark:hover:bg-slate-800/40 transition-colors group">
                      <td className="px-6 py-4">
                        <div className="flex flex-col gap-1">
                          <div className="flex items-center gap-2">
                            <span className="text-[10px] font-black bg-blue-50 dark:bg-blue-900/30 text-blue-600 px-1.5 w-fit rounded uppercase">{req.productCode}</span>
                            {req.isValidadeCurta && (
                              <span className="text-[8px] font-black bg-orange-100 text-orange-600 dark:bg-orange-900/30 dark:text-orange-400 px-1.5 py-0.5 rounded flex items-center gap-1 uppercase">
                                <Timer className="w-2.5 h-2.5" /> Val. Curta
                              </span>
                            )}
                          </div>
                          <p className="text-[11px] font-bold dark:text-slate-200 line-clamp-1">{req.productName}</p>
                          {req.productSabor && (
                             <p className="text-[9px] font-black text-pink-500 uppercase">{req.productSabor}</p>
                          )}
                          {req.observacoes && (
                            <p className="text-[9px] text-blue-500 font-medium italic mt-0.5 max-w-xs truncate">"{req.observacoes}"</p>
                          )}
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex flex-col gap-1">
                          <span className="text-[11px] font-black text-gray-700 dark:text-slate-300 uppercase">{req.quantidade} {req.unidade}</span>
                          <span className="text-[8px] font-bold text-gray-400 uppercase">{req.tipo}</span>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex justify-center gap-3">
                          <button 
                            type="button"
                            onClick={() => handleEditRequest(req)}
                            className="flex flex-col items-center gap-1 group/btn"
                            title="Editar"
                          >
                            <div className="p-2.5 bg-blue-50 dark:bg-blue-900/20 text-blue-600 group-hover/btn:bg-blue-600 group-hover/btn:text-white rounded-xl transition-all shadow-sm">
                              <Edit3 className="w-4 h-4" />
                            </div>
                          </button>
                          <button 
                            type="button"
                            onClick={(e) => {
                              e.stopPropagation();
                              if (window.confirm('Deseja realmente excluir este item do pedido?')) {
                                onDeleteRequest(req.id);
                              }
                            }}
                            className="flex flex-col items-center gap-1 group/btn"
                            title="Excluir"
                          >
                            <div className="p-2.5 bg-red-50 dark:bg-red-900/20 text-red-600 group-hover/btn:bg-red-600 group-hover/btn:text-white rounded-xl transition-all shadow-sm">
                              <Trash2 className="w-4 h-4" />
                            </div>
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </div>
      )}

      {selected && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-sm animate-in fade-in">
          <div className="bg-white dark:bg-slate-900 w-full max-w-md rounded-3xl shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-800 animate-in zoom-in-95">
            <div className="p-6 border-b dark:border-slate-800 flex justify-between items-center bg-gray-50/50 dark:bg-slate-800/30">
              <div>
                <h3 className="text-lg font-black dark:text-white uppercase leading-tight">
                  {editingRequestId ? 'Editar Item' : 'Configurar Item'}
                </h3>
                <div className="flex items-center gap-2 mt-1">
                  <p className="text-[10px] font-bold text-blue-500 uppercase line-clamp-1">{selected.produto}</p>
                </div>
                {selected.sabor && (
                  <p className="text-[9px] font-black text-pink-500 uppercase flex items-center gap-1 mt-1">
                    <Candy className="w-2.5 h-2.5" /> Sabor: {selected.sabor}
                  </p>
                )}
              </div>
              <button onClick={() => { setSelected(null); setEditingRequestId(null); }} className="p-2 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-xl transition-colors"><X className="w-5 h-5 text-gray-400" /></button>
            </div>

            <form onSubmit={handleSendRequest} className="p-6 space-y-4 max-h-[70vh] overflow-y-auto custom-scrollbar">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black uppercase text-gray-400 px-1 flex items-center gap-1 group/tooltip relative">
                    Quantidade
                    <Info className="w-3 h-3 text-gray-300 cursor-help" />
                    <span className="invisible group-hover/tooltip:visible absolute bottom-full left-0 mb-2 w-48 p-2 bg-slate-800 text-white text-[9px] font-medium rounded-lg shadow-xl z-50 normal-case tracking-normal">
                      Informe o volume desejado baseado na unidade (UN, CX, etc).
                    </span>
                  </label>
                  <input type="number" min="1" required className="w-full px-4 py-4 bg-gray-50 dark:bg-slate-800 rounded-xl font-bold dark:text-white outline-none border-2 border-transparent focus:border-blue-500 transition-all shadow-inner" value={quant} onChange={e => setQuant(parseInt(e.target.value))} />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black uppercase text-gray-400 px-1">Unidade</label>
                  <select className="w-full px-4 py-4 bg-gray-50 dark:bg-slate-800 rounded-xl font-bold dark:text-white outline-none border-2 border-transparent focus:border-blue-500 transition-all shadow-inner" value={unit} onChange={e => setUnit(e.target.value as UnitType)}>
                    {UNIT_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
                  </select>
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-black uppercase text-gray-400 px-1 flex items-center gap-1 group/tooltip relative">
                  Natureza do Pedido
                  <Info className="w-3 h-3 text-gray-300 cursor-help" />
                  <span className="invisible group-hover/tooltip:visible absolute bottom-full left-0 mb-2 w-56 p-2 bg-slate-800 text-white text-[9px] font-medium rounded-lg shadow-xl z-50 normal-case tracking-normal">
                    Aposta: Previsão de venda futura. <br/> Garantida: Pedido para venda já realizada.
                  </span>
                </label>
                <div className="grid grid-cols-2 gap-2">
                  <button type="button" onClick={() => setType('Aposta na Venda')} className={`py-4 rounded-xl text-[10px] font-black uppercase border-2 transition-all ${type === 'Aposta na Venda' ? 'bg-blue-600 border-blue-600 text-white shadow-lg shadow-blue-500/30' : 'bg-gray-50 dark:bg-slate-800 border-transparent text-gray-400 hover:bg-gray-100'}`}>Aposta na Venda</button>
                  <button type="button" onClick={() => setType('Venda Garantida')} className={`py-4 rounded-xl text-[10px] font-black uppercase border-2 transition-all ${type === 'Venda Garantida' ? 'bg-blue-600 border-blue-600 text-white shadow-lg shadow-blue-500/30' : 'bg-gray-50 dark:bg-slate-800 border-transparent text-gray-400 hover:bg-gray-100'}`}>Venda Garantida</button>
                </div>
              </div>

              <div className="space-y-1.5 pt-2">
                <button 
                  type="button" 
                  onClick={() => setIsValidadeCurta(!isValidadeCurta)} 
                  className={`w-full flex items-center justify-between px-5 py-4 rounded-xl border-2 transition-all ${isValidadeCurta ? 'bg-orange-50 border-orange-500 text-orange-700 shadow-sm' : 'bg-gray-50 dark:bg-slate-800 border-transparent text-gray-400'}`}
                >
                  <div className="flex items-center gap-3">
                    <Timer className={`w-5 h-5 ${isValidadeCurta ? 'text-orange-500' : 'text-gray-400'}`} />
                    <span className="text-[10px] font-black uppercase tracking-widest">Validade Curta?</span>
                  </div>
                  <div className={`w-5 h-5 rounded-md border-2 flex items-center justify-center transition-colors ${isValidadeCurta ? 'bg-orange-500 border-orange-500' : 'border-gray-200 dark:border-slate-700'}`}>
                    {isValidadeCurta && <Check className="w-3 h-3 text-white stroke-[4]" />}
                  </div>
                </button>
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-black uppercase text-gray-400 px-1 flex items-center gap-1">
                  <MessageSquareText className="w-3 h-3 text-blue-500" /> Observações (Opcional)
                </label>
                <textarea 
                  placeholder="Ex: Urgente para amanhã..." 
                  className="w-full px-4 py-3 bg-gray-50 dark:bg-slate-800 rounded-xl font-medium text-xs dark:text-white outline-none border-2 border-transparent focus:border-blue-500 transition-all shadow-inner h-20 resize-none"
                  value={observacoes}
                  onChange={e => setObservacoes(e.target.value)}
                />
              </div>

              <button 
                disabled={isSubmitting || !solicitante} 
                type="submit" 
                className={`w-full font-black py-6 rounded-2xl flex items-center justify-center gap-4 uppercase text-sm tracking-[0.15em] shadow-2xl active:scale-95 transition-all mt-6 ${requestStatus === 'success' ? 'bg-emerald-500 text-white ring-4 ring-emerald-500/20' : 'bg-blue-600 hover:bg-blue-700 text-white ring-4 ring-blue-600/10'}`}
              >
                {isSubmitting ? (
                  <RefreshCw className="w-6 h-6 animate-spin" />
                ) : requestStatus === 'success' ? (
                  <><CheckCircle2 className="w-6 h-6" /> {editingRequestId ? 'ATUALIZADO!' : 'ADICIONADO!'}</>
                ) : (
                  <><PlusCircle className="w-6 h-6" /> {editingRequestId ? 'SALVAR ALTERAÇÕES' : 'ADICIONAR AO PEDIDO'}</>
                )}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { UserPortal } from './components/UserPortal';
import { AdminPortal } from './components/AdminPortal';
import { AppState, Product, StockRequest, WhatsAppConfig, UpdateLog } from './types';
import { LayoutDashboard, ShieldCheck, Sun, Moon, KeyRound, LogOut, ChevronRight, Store, X, Loader2 } from 'lucide-react';
import Papa from 'papaparse';

const THEME_KEY = 'marsil_theme_pref';
const AUTH_KEY = 'marsil_auth_role';
const PRODUCTS_KEY = 'marsil_local_products';
const VENDEDORES_KEY = 'marsil_vendedores_list';
const REQUESTS_KEY = 'marsil_requests_history';
const SYNC_URL_KEY = 'marsil_sync_url';
const UPDATE_HISTORY_KEY = 'marsil_update_history';

const PASSWORDS = {
  VENDOR: '@marsil2026',
  ADMIN: '@adminMarsil2026'
};

const DEFAULT_VENDEDORES = [
  "ADALTON LUIZ", "AIRTON DONIZETTI", "ANA CAMARGO", "ANA PAULA", "CARLOS ROSEIRO",
  "DOUGLAS PITELLI", "EDMILSON LEAL", "FERNANDO APARECIDO", "GUSTAVO PAULINO",
  "JOAO JOSE", "JOAO MANUEL", "LEONARDO APARECIDO", "LUIS ALEXANDRE",
  "MARCELO SANTOS", "MARCO AURELIO", "NIVALDO NEVES", "ROSIMAR FREITAS",
  "ROZIMARA SOUZA", "TELMA CRISTINA", "WASHINGTON BELMIRO", "OUTRO"
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'user' | 'admin'>('user');
  const [authRole, setAuthRole] = useState<'none' | 'vendor' | 'admin'>(() => {
    return (localStorage.getItem(AUTH_KEY) as any) || 'none';
  });

  const [loginTarget, setLoginTarget] = useState<'vendedor' | 'admin' | null>(null);
  const [passwordInput, setPasswordInput] = useState('');
  const [loginError, setLoginError] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);

  const [isDarkMode, setIsDarkMode] = useState(() => {
    const savedTheme = localStorage.getItem(THEME_KEY);
    return savedTheme === 'dark';
  });

  const [appState, setAppState] = useState<AppState>(() => {
    const savedProducts = localStorage.getItem(PRODUCTS_KEY);
    const savedVendedores = localStorage.getItem(VENDEDORES_KEY);
    const savedRequests = localStorage.getItem(REQUESTS_KEY);
    const savedHistory = localStorage.getItem(UPDATE_HISTORY_KEY);

    let finalVendedores = DEFAULT_VENDEDORES;
    if (savedVendedores) {
      try {
        const parsed = JSON.parse(savedVendedores);
        if (Array.isArray(parsed) && parsed.length > 0) finalVendedores = parsed;
      } catch (e) { finalVendedores = DEFAULT_VENDEDORES; }
    }

    return { 
      products: savedProducts ? JSON.parse(savedProducts) : [], 
      requests: savedRequests ? JSON.parse(savedRequests) : [], 
      vendedores: finalVendedores,
      whatsappConfig: { enabled: true, phoneNumber: '5511999999999' },
      updateHistory: savedHistory ? JSON.parse(savedHistory) : []
    };
  });

  const mapCSVData = (data: any[]): Product[] => {
    return data.map((row: any, i: number) => {
      const findVal = (keys: string[]) => {
        const key = Object.keys(row).find(k => 
          keys.some(s => k.trim().toLowerCase() === s.toLowerCase()) ||
          keys.some(s => k.trim().toLowerCase().includes(s.toLowerCase()))
        );
        return key ? String(row[key]).trim() : '';
      };

      return {
        id: `p-${i}-${Date.now()}`,
        fornecedor: findVal(['Fornecedor', 'Forn', 'Marca', 'Fabricante']),
        codigo: findVal(['Código', 'Cód', 'Ref', 'Cod Item', 'Item', 'codigo', 'ID', 'Referência']),
        situacao: findVal(['Situação', 'Status', 'Sit', 'Disponibilidade']),
        comprador: findVal(['Comprador', 'Responsável', 'Buyer']),
        produto: findVal(['Produto', 'Descrição', 'Nome', 'Desc', 'produto']),
        sabor: findVal(['Sabor', 'Gosto', 'Flavor', 'Variante']),
        embalagem: findVal(['Embalagem', 'Emb', 'Pack']),
        estoqueMarsil: parseInt(findVal(['Marsil', 'SP', 'Estoque Marsil', 'Matriz'])) || 0,
        estoqueBoraceia: parseInt(findVal(['Boraceia', 'Boracéia', 'Filial', 'Estoque Boraceia'])) || 0,
      };
    }).filter(p => p.produto && p.produto !== '');
  };

  const syncData = useCallback(async (url: string) => {
    setIsSyncing(true);
    return new Promise<void>((resolve, reject) => {
      Papa.parse(url, {
        download: true,
        header: true,
        skipEmptyLines: true,
        complete: (results) => {
          const mapped = mapCSVData(results.data);
          if (mapped.length > 0) {
            setAppState(prev => {
              const newLog: UpdateLog = {
                id: Date.now().toString(),
                timestamp: new Date().toISOString(),
                fileName: 'Sincronização Automática',
                recordCount: mapped.length,
                status: 'success'
              };

              return { 
                ...prev, 
                products: mapped,
                updateHistory: [newLog, ...prev.updateHistory].slice(0, 20)
              };
            });
          }
          setIsSyncing(false);
          resolve();
        },
        error: (error) => {
          console.error("Erro na sincronização:", error);
          setIsSyncing(false);
          reject(error);
        }
      });
    });
  }, []);

  const handleManualRefresh = async () => {
    const url = localStorage.getItem(SYNC_URL_KEY);
    if (url) {
      await syncData(url);
    } else {
      alert("Nenhum link de sincronização configurado pelo administrador.");
    }
  };

  useEffect(() => {
    const initApp = async () => {
      const params = new URLSearchParams(window.location.search);
      const urlSync = params.get('s');
      const urlVendors = params.get('v');
      const storedSyncUrl = localStorage.getItem(SYNC_URL_KEY);

      let initialVendedores = appState.vendedores;

      if (urlVendors) {
        try {
          const parsed = JSON.parse(decodeURIComponent(urlVendors));
          if (Array.isArray(parsed) && parsed.length > 0) {
            initialVendedores = parsed;
            localStorage.setItem(VENDEDORES_KEY, JSON.stringify(parsed));
          }
        } catch (e) { console.error(e); }
      }

      const finalSyncUrl = urlSync || storedSyncUrl;

      if (finalSyncUrl) {
        if (urlSync) localStorage.setItem(SYNC_URL_KEY, urlSync);
        try {
          await syncData(finalSyncUrl);
        } catch (e) {
          console.error("Falha ao sincronizar dados iniciais.");
        } finally {
          setIsLoading(false);
        }
      } else {
        if (urlVendors) setAppState(prev => ({ ...prev, vendedores: initialVendedores }));
        setTimeout(() => setIsLoading(false), 800);
      }
    };
    initApp();
  }, []);

  useEffect(() => { localStorage.setItem(AUTH_KEY, authRole); }, [authRole]);
  useEffect(() => {
    localStorage.setItem(PRODUCTS_KEY, JSON.stringify(appState.products));
    localStorage.setItem(VENDEDORES_KEY, JSON.stringify(appState.vendedores));
    localStorage.setItem(REQUESTS_KEY, JSON.stringify(appState.requests));
    localStorage.setItem(UPDATE_HISTORY_KEY, JSON.stringify(appState.updateHistory));
  }, [appState]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem(THEME_KEY, 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem(THEME_KEY, 'light');
    }
  }, [isDarkMode]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const requiredPass = loginTarget === 'admin' ? PASSWORDS.ADMIN : PASSWORDS.VENDOR;
    if (passwordInput === requiredPass) {
      const role = loginTarget === 'admin' ? 'admin' : 'vendor';
      setAuthRole(role);
      setActiveTab(loginTarget === 'admin' ? 'admin' : 'user');
      setLoginError(false);
      setLoginTarget(null);
    } else {
      setLoginError(true);
      setTimeout(() => setLoginError(false), 3000);
    }
    setPasswordInput('');
  };

  const handleLogout = () => {
    setAuthRole('none');
    setLoginTarget(null);
    setPasswordInput('');
    setActiveTab('user');
    localStorage.removeItem(AUTH_KEY);
  };

  const handleUploadData = (newProducts: Product[]) => {
    setAppState(prev => ({ ...prev, products: newProducts }));
  };

  const handleRegisterUpdate = (log: UpdateLog) => {
    setAppState(prev => ({
      ...prev,
      updateHistory: [log, ...prev.updateHistory].slice(0, 20)
    }));
  };

  const handleAddVendedor = (name: string) => {
    if (!appState.vendedores.includes(name)) {
      setAppState(prev => ({ ...prev, vendedores: [...prev.vendedores, name].sort() }));
    }
  };

  const handleRemoveVendedor = (name: string) => {
    setAppState(prev => ({ ...prev, vendedores: prev.vendedores.filter(v => v !== name) }));
  };

  const handleUpdateWhatsApp = (config: WhatsAppConfig) => {
    setAppState(prev => ({ ...prev, whatsappConfig: config }));
  };

  const handleSubmitRequest = (request: StockRequest) => {
    setAppState(prev => ({ ...prev, requests: [request, ...prev.requests] }));
  };

  const handleUpdateRequest = (updatedRequest: StockRequest) => {
    setAppState(prev => ({
      ...prev,
      requests: prev.requests.map(r => String(r.id) === String(updatedRequest.id) ? updatedRequest : r)
    }));
  };

  const handleDeleteRequest = useCallback((requestId: string) => {
    setAppState(prev => ({ ...prev, requests: prev.requests.filter(r => String(r.id) !== String(requestId)) }));
  }, []);

  const handleClearUserRequests = useCallback((solicitante: string) => {
    setAppState(prev => ({ ...prev, requests: prev.requests.filter(r => r.solicitante !== solicitante) }));
  }, []);

  const handleUpdateRequestStatus = (requestId: string, status: StockRequest['status']) => {
    setAppState(prev => ({
      ...prev,
      requests: prev.requests.map(r => String(r.id) === String(requestId) ? { ...r, status } : r)
    }));
  };

  const handleClearRequests = () => {
    if (window.confirm('Limpar histórico local de pedidos?')) {
      setAppState(prev => ({ ...prev, requests: [] }));
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-slate-950">
        <div className="flex flex-col items-center gap-4">
          <Loader2 className="w-8 h-8 text-blue-600 animate-spin" />
          <p className="text-[10px] font-black uppercase tracking-widest text-gray-400">Sincronizando Dados...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-slate-950 text-gray-900 dark:text-slate-100 transition-colors duration-300">
      <header className="bg-white dark:bg-slate-900 border-b border-gray-200 dark:border-slate-800 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <div className="bg-blue-600 p-2 rounded-xl shrink-0">
                <LayoutDashboard className="w-5 h-5 text-white" />
              </div>
              <div className="flex flex-col">
                <h1 className="text-lg font-black tracking-tight dark:text-white">Marsil & Boracéia</h1>
                <p className="text-[9px] text-gray-400 font-bold uppercase tracking-tighter">Gestão de Estoque</p>
              </div>
            </div>
            <div className="flex items-center gap-4">
              <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-gray-400 hover:text-blue-500 transition-colors">
                {isDarkMode ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
              </button>
              {authRole !== 'none' && (
                <div className="flex items-center gap-2">
                  <div className="bg-gray-100 dark:bg-slate-800 p-1 rounded-xl flex">
                    <button onClick={() => setActiveTab('user')} className={`px-3 py-1.5 text-[10px] font-black rounded-lg uppercase ${activeTab === 'user' ? 'bg-white dark:bg-slate-700 text-blue-600 shadow-sm' : 'text-gray-400'}`}>Consulta</button>
                    {authRole === 'admin' && (
                      <button onClick={() => setActiveTab('admin')} className={`px-3 py-1.5 text-[10px] font-black rounded-lg uppercase ${activeTab === 'admin' ? 'bg-white dark:bg-slate-700 text-blue-600 shadow-sm' : 'text-gray-400'}`}>Admin</button>
                    )}
                  </div>
                  <button onClick={handleLogout} className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-xl transition-colors"><LogOut className="w-4 h-4" /></button>
                </div>
              )}
            </div>
          </div>
        </div>
      </header>
      <main className="flex-grow p-4 sm:p-8 flex flex-col items-center">
        {authRole === 'none' ? (
          !loginTarget ? (
            <div className="w-full max-w-2xl mt-12 animate-in fade-in zoom-in-95 duration-500 space-y-8">
              <div className="text-center space-y-2">
                <h2 className="text-4xl font-black dark:text-white tracking-tight">Painel de Estoque</h2>
                <p className="text-gray-500 dark:text-slate-400 text-sm">Acesse para consultar itens e realizar pedidos.</p>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <button onClick={() => setLoginTarget('vendedor')} className="group bg-white dark:bg-slate-900 p-8 rounded-3xl shadow-xl hover:shadow-2xl border-2 border-transparent hover:border-emerald-500 transition-all flex flex-col items-center space-y-4">
                  <div className="w-16 h-16 bg-emerald-50 dark:bg-emerald-900/30 rounded-2xl flex items-center justify-center group-hover:bg-emerald-600 group-hover:text-white transition-all">
                    <Store className="w-8 h-8 text-emerald-600 group-hover:text-white" />
                  </div>
                  <h3 className="text-xl font-bold dark:text-white">Vendedor</h3>
                  <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Acessar <ChevronRight className="w-4 h-4 inline" /></p>
                </button>
                <button onClick={() => setLoginTarget('admin')} className="group bg-white dark:bg-slate-900 p-8 rounded-3xl shadow-xl hover:shadow-2xl border-2 border-transparent hover:border-blue-500 transition-all flex flex-col items-center space-y-4">
                  <div className="w-16 h-16 bg-blue-50 dark:bg-blue-900/30 rounded-2xl flex items-center justify-center group-hover:bg-blue-600 group-hover:text-white transition-all">
                    <ShieldCheck className="w-8 h-8 text-blue-600 group-hover:text-white" />
                  </div>
                  <h3 className="text-xl font-bold dark:text-white">Administrador</h3>
                  <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Configurar <ChevronRight className="w-4 h-4 inline" /></p>
                </button>
              </div>
            </div>
          ) : (
            <div className="w-full max-w-sm mt-12 animate-in slide-in-from-bottom-8 duration-500 px-4">
              <div className="bg-white dark:bg-slate-900 p-8 rounded-3xl shadow-2xl border border-gray-100 dark:border-slate-800 text-center relative">
                <button onClick={() => setLoginTarget(null)} className="absolute left-4 top-4 p-2 text-gray-400 hover:text-gray-600 transition-colors"><X className="w-4 h-4" /></button>
                <div className={`w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-6 ${loginTarget === 'admin' ? 'bg-blue-50 dark:bg-blue-900/30' : 'bg-emerald-50 dark:bg-emerald-900/30'}`}>
                  {loginTarget === 'admin' ? <ShieldCheck className="w-8 h-8 text-blue-600" /> : <Store className="w-8 h-8 text-emerald-600" />}
                </div>
                <h2 className="text-2xl font-black dark:text-white mb-6">Login {loginTarget === 'admin' ? 'Admin' : 'Vendedor'}</h2>
                <form onSubmit={handleLogin} className="space-y-4">
                  <div className="relative">
                    <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                    <input autoFocus type="password" placeholder="Sua senha..." value={passwordInput} onChange={(e) => setPasswordInput(e.target.value)} className="w-full pl-12 pr-4 py-4 rounded-2xl border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 outline-none transition-all dark:text-white font-bold" />
                  </div>
                  {loginError && <p className="text-[10px] text-red-500 font-bold uppercase">Senha incorreta!</p>}
                  <button type="submit" className="w-full bg-blue-600 text-white font-black py-4 rounded-2xl shadow-lg active:scale-95 transition-all uppercase tracking-widest text-xs">Entrar</button>
                </form>
              </div>
            </div>
          )
        ) : (
          activeTab === 'user' ? (
            <UserPortal 
              products={appState.products} 
              requests={appState.requests} 
              vendedores={appState.vendedores} 
              whatsappConfig={appState.whatsappConfig} 
              onSubmitRequest={handleSubmitRequest}
              onDeleteRequest={handleDeleteRequest}
              onClearUserRequests={handleClearUserRequests}
              onUpdateRequest={handleUpdateRequest}
              isSyncing={isSyncing}
              onManualRefresh={handleManualRefresh}
              lastUpdate={appState.updateHistory[0]?.timestamp}
            />
          ) : (
            <AdminPortal 
              appState={appState} 
              onUploadData={handleUploadData} 
              onRegisterUpdate={handleRegisterUpdate}
              onAddVendedor={handleAddVendedor} 
              onRemoveVendedor={handleRemoveVendedor} 
              onUpdateWhatsApp={handleUpdateWhatsApp} 
              onUpdateRequestStatus={handleUpdateRequestStatus} 
              onClearRequests={handleClearRequests} 
            />
          )
        )}
      </main>
    </div>
  );
};

export default App;
